# ── EMBEDDED SMARTLAB ASSETS (Zero external file dependencies) ──
SMARTLAB_LOGO_BASE64 = """"""

def get_embedded_logo_pixmap() -> QPixmap:
    pix = QPixmap()
    try:
        data = base64.b64decode(SMARTLAB_LOGO_BASE64)
        pix.loadFromData(data)
    except Exception as e:
        logger.warning(f"Could not load embedded logo: {e}")
    return pix

def get_embedded_logo_icon() -> QIcon:
    pix = get_embedded_logo_pixmap()
    if not pix.isNull():
        return QIcon(pix)
    return QIcon()



