# ============================================================
# HYPERLUMA - Eye Disease Detection System
# SMART - Sanjivani Multidisciplinary AI Research & Technology
# models/explainability.py - AI Attention & Explainability Generator
# ============================================================

import torch
import torch.nn as nn
import torch.nn.functional as F
import numpy as np
import cv2
from PIL import Image
from torchvision import transforms
from loguru import logger

IMAGENET_MEAN = [0.485, 0.456, 0.406]
IMAGENET_STD  = [0.229, 0.224, 0.225]
IMAGE_SIZE    = 640


class ExplainabilityGenerator:
    """
    Generates class-activation attention / explainability maps (Grad-CAM & Saliency)
    for HYPERLUMA neural network architectures without modifying model weights.
    
    Supports:
    - Convolutional architectures (EfficientNetV2-S, ResNeXt50)
    - Transformer architectures (Swin Transformer)
    - Custom Fourier & Attention architectures (FNet, Perceiver IO)
    """

    def __init__(self, model: nn.Module):
        self.model = model
        self.device = next(model.parameters()).device
        self.transform = transforms.Compose([
            transforms.Resize((IMAGE_SIZE, IMAGE_SIZE)),
            transforms.ToTensor(),
            transforms.Normalize(mean=IMAGENET_MEAN, std=IMAGENET_STD),
        ])

    def generate_attention_map(
        self,
        image_bgr: np.ndarray,
        target_class_idx: int,
        alpha: float = 0.45,
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
        """
        Generates class-specific activation overlay for the predicted disease class.

        Args:
            image_bgr: Input OpenCV BGR image (H x W x 3)
            target_class_idx: Target disease class index (0..5)
            alpha: Blend weight for heat map overlay (0.0 to 1.0)

        Returns:
            blended_overlay: BGR image with AI attention heatmap overlay
            colored_heatmap: Pure BGR colored heatmap
            raw_heatmap: Normalized grayscale float heatmap [0.0, 1.0]
        """
        if image_bgr is None or image_bgr.size == 0:
            raise ValueError("Input image is invalid or empty.")

        orig_h, orig_w = image_bgr.shape[:2]

        # Preprocess input image to tensor
        rgb = cv2.cvtColor(image_bgr, cv2.COLOR_BGR2RGB)
        pil_img = Image.fromarray(rgb)
        input_tensor = self.transform(pil_img).unsqueeze(0).to(self.device)
        input_tensor.requires_grad_(True)

        raw_heatmap = None

        # Attempt Grad-CAM on convolutional / layer-based features first
        try:
            raw_heatmap = self._gradcam(input_tensor, target_class_idx)
        except Exception as err:
            logger.debug(f"Grad-CAM hook fallback triggered: {err}")

        # Fallback to Saliency / Input Gradient Map if Grad-CAM unavailable for architecture
        if raw_heatmap is None or raw_heatmap.max() == 0:
            raw_heatmap = self._gradient_saliency(input_tensor, target_class_idx)

        # Resize heatmap to original image spatial size
        raw_heatmap = cv2.resize(raw_heatmap, (orig_w, orig_h), interpolation=cv2.INTER_CUBIC)
        # Apply heavy Gaussian Blur to smooth out blocky transformer artifacts and make it look like a smooth blob
        raw_heatmap = cv2.GaussianBlur(raw_heatmap, (99, 99), 0)
        raw_heatmap = raw_heatmap - np.min(raw_heatmap)
        if np.max(raw_heatmap) > 0:
            raw_heatmap = raw_heatmap / np.max(raw_heatmap)
        raw_heatmap = np.clip(raw_heatmap, 0.0, 1.0)

        # Apply TURBO/JET colormap for medical visualization
        heatmap_uint8 = (raw_heatmap * 255.0).astype(np.uint8)
        colored_heatmap = cv2.applyColorMap(heatmap_uint8, cv2.COLORMAP_TURBO)

        # Blend heatmap over original fundus image
        blended_overlay = cv2.addWeighted(
            image_bgr, 1.0 - alpha, colored_heatmap, alpha, 0
        )

        return blended_overlay, colored_heatmap, raw_heatmap

    def _gradcam(self, input_tensor: torch.Tensor, target_class_idx: int) -> np.ndarray | None:
        """Computes Grad-CAM++ map from target feature layer."""
        target_layer = self._find_target_layer()
        if target_layer is None:
            return None

        activations = []
        gradients = []

        def forward_hook(module, input, output):
            activations.append(output)

        def backward_hook(module, grad_in, grad_out):
            gradients.append(grad_out[0])

        h1 = target_layer.register_forward_hook(forward_hook)
        h2 = target_layer.register_full_backward_hook(backward_hook)

        try:
            self.model.zero_grad()
            output = self.model(input_tensor)
            if output.ndim > 1:
                score = output[0, target_class_idx]
            else:
                score = output[target_class_idx]

            score.backward(retain_graph=False)

            if not activations or not gradients:
                return None

            act = activations[0].detach()
            grad = gradients[0].detach()

            # Handle 4D Conv feature maps (B, C, H, W) or Swin (B, H, W, C)
            if act.ndim == 4:
                # Swin Transformers output (B, H, W, C). We need (B, C, H, W).
                # Usually channels is larger than H, W in final layers.
                if act.shape[-1] > act.shape[1] and act.shape[1] == act.shape[2]:
                    act = act.permute(0, 3, 1, 2)
                    grad = grad.permute(0, 3, 1, 2)

                # Grad-CAM++ Alpha Coefficients
                alpha_num = grad.pow(2)
                alpha_denom = 2.0 * grad.pow(2) + torch.sum(act * grad.pow(3), dim=(2, 3), keepdim=True)
                alpha_denom = torch.where(alpha_denom != 0.0, alpha_denom, torch.ones_like(alpha_denom))
                alphas = alpha_num / alpha_denom

                weights = torch.sum(alphas * F.relu(grad), dim=(2, 3), keepdim=True)
                cam = torch.sum(weights * act, dim=1, keepdim=True)
                cam = F.relu(cam)
                cam = cam.squeeze().cpu().numpy()

            # Handle 3D Transformer patch features (B, N, C)
            elif act.ndim == 3:
                # Grad-CAM++ Alpha Coefficients for 1D sequence
                alpha_num = grad.pow(2)
                alpha_denom = 2.0 * grad.pow(2) + torch.sum(act * grad.pow(3), dim=1, keepdim=True)
                alpha_denom = torch.where(alpha_denom != 0.0, alpha_denom, torch.ones_like(alpha_denom))
                alphas = alpha_num / alpha_denom
                
                weights = torch.sum(alphas * F.relu(grad), dim=1, keepdim=True)
                cam = torch.sum(weights * act, dim=-1)
                cam = F.relu(cam).squeeze().cpu().numpy()
                side = int(np.sqrt(cam.shape[0]))
                if side * side == cam.shape[0]:
                    cam = cam.reshape(side, side)
                else:
                    return None
            else:
                return None

            cam = cam - np.min(cam)
            max_val = np.max(cam)
            if max_val > 1e-7:
                cam = cam / max_val

            return cam.astype(np.float32)

        finally:
            h1.remove()
            h2.remove()

    def _gradient_saliency(self, input_tensor: torch.Tensor, target_class_idx: int) -> np.ndarray:
        """Fallback input gradient saliency map for non-standard layers."""
        self.model.zero_grad()
        output = self.model(input_tensor)
        score = output[0, target_class_idx]
        score.backward()

        grad = input_tensor.grad.data.abs().squeeze().cpu().numpy()
        # Average gradients across RGB channels
        saliency = np.mean(grad, axis=0)

        # Smooth saliency map for clean spatial visual focus
        saliency = cv2.GaussianBlur(saliency, (21, 21), 0)
        saliency = saliency - np.min(saliency)
        max_val = np.max(saliency)
        if max_val > 1e-7:
            saliency = saliency / max_val

        return saliency.astype(np.float32)

    def _find_target_layer(self) -> nn.Module | None:
        """Identifies final feature/convolutional layer for target architecture."""
        target_model = self.model
        if hasattr(self.model, "model_a") and hasattr(self.model, "model_b"):
            # For ensemble models, inspect the dominant sub-model (or model_a)
            weight_a = getattr(self.model, "weight_a", 0.5)
            target_model = self.model.model_a if weight_a >= 0.5 else self.model.model_b

        # 1. ResNeXt / ResNet
        if hasattr(target_model, "layer4"):
            return target_model.layer4

        # 2. EfficientNet
        if hasattr(target_model, "conv_head"):
            return target_model.conv_head
        if hasattr(target_model, "blocks"):
            return target_model.blocks[-1]

        # 3. Swin Transformer
        if hasattr(target_model, "layers"):
            return target_model.layers[-1]

        # 4. Custom FNet / Perceiver
        if hasattr(target_model, "blocks"):
            return target_model.blocks[-1]
        if hasattr(target_model, "cross_attn"):
            return target_model.cross_attn[-1]

        # Search recursively for last Conv2d or LayerNorm module
        target = None
        for m in target_model.modules():
            if isinstance(m, (nn.Conv2d, nn.LayerNorm)):
                target = m
        return target



