import torch
import torch.nn as nn
import timm
import os
from loguru import logger
# [Bundled] from models.custom_models import build_fnet, build_perceiver, EnsembleModel

# ── Disease Classes ────────────────────────────────────────
CLASSES     = ["AMD", "Cataract", "Dementia", "Diabetes", "Glaucoma", "Normal"]
NUM_CLASSES = len(CLASSES)
IMAGE_SIZE  = 640

CUSTOM_ARCHITECTURES = {"fnet", "perceiver"}


class ModelLoader:

    def __init__(self):
        self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        logger.info(f"Device: {self.device}")

    def load_model(self, architecture, weight_path: str) -> nn.Module:
        if isinstance(architecture, dict) or architecture == "ensemble" or (isinstance(weight_path, str) and weight_path.endswith("_ensemble.pth")):
            info = architecture if isinstance(architecture, dict) else {}
            return self.load_ensemble_model(info, weight_path)

        if not os.path.exists(weight_path):
            raise FileNotFoundError(f"Weight file not found: {weight_path}")
        logger.info(f"Loading architecture : {architecture}")
        logger.info(f"Weight file          : {weight_path}")
        model = self._build_model(architecture)
        model = self._load_weights(model, weight_path)
        model = model.to(self.device)
        model.eval()
        logger.info(f"Model ready on {self.device}")
        return model

    def load_ensemble_model(self, ensemble_info: dict, weight_path: str = None) -> nn.Module:
        """
        Loads an ensemble model consisting of two sub-models with weighted soft voting.
        Supports loading from pre-saved ensemble .pth checkpoints or fallback to base weights.
        """
        logger.info(f"Loading Ensemble Model: {ensemble_info.get('name', weight_path)}")
        weights_dir = os.path.dirname(weight_path) if weight_path else "."

        # Identify sub-model architectures and weight keys
        models_list = ensemble_info.get("models", [])
        base_files = ensemble_info.get("base_files", [])
        weight_val = 0.5

        # Check if saved ensemble checkpoint exists
        loaded_from_checkpoint = False
        checkpoint = None
        if weight_path and os.path.exists(weight_path):
            try:
                checkpoint = torch.load(weight_path, map_location=self.device, weights_only=False)
                if isinstance(checkpoint, dict):
                    loaded_from_checkpoint = True
                    logger.info(f"Loaded ensemble checkpoint from: {weight_path}")
            except Exception as e:
                logger.warning(f"Could not load ensemble checkpoint directly ({e}). Falling back to base weights.")

        # Determine models and weights from checkpoint or ensemble_info
        if loaded_from_checkpoint and checkpoint:
            # Detect state dict keys in checkpoint
            keys = list(checkpoint.keys())
            state_keys = [k for k in keys if k.endswith("_state_dict")]
            weight_keys = [k for k in keys if k.startswith("w_")]

            if len(state_keys) >= 2:
                # Infer architectures from keys or ensemble_info
                key_a, key_b = state_keys[0], state_keys[1]
                arch_a = self._infer_arch_from_key(key_a, models_list, 0)
                arch_b = self._infer_arch_from_key(key_b, models_list, 1)

                model_a = self._build_model(arch_a)
                model_b = self._build_model(arch_b)

                dict_a = self._clean_state_dict(checkpoint[key_a])
                dict_b = self._clean_state_dict(checkpoint[key_b])

                model_a.load_state_dict(dict_a, strict=False)
                model_b.load_state_dict(dict_b, strict=False)

                if weight_keys:
                    weight_val = float(checkpoint[weight_keys[0]])
                elif "weights" in ensemble_info and isinstance(ensemble_info["weights"], dict):
                    weight_val = list(ensemble_info["weights"].values())[0]

                model_a = model_a.to(self.device).eval()
                model_b = model_b.to(self.device).eval()

                name_a = arch_a
                name_b = arch_b
                ensemble = EnsembleModel(model_a, model_b, weight_val, name_a, name_b).to(self.device)
                ensemble.eval()
                logger.info(f"Ensemble loaded successfully from checkpoint (w_a={weight_val:.2f})")
                return ensemble

        # Fallback: Load individual models from base weights
        if len(models_list) >= 2 and len(base_files) >= 2:
            arch_a, arch_b = models_list[0], models_list[1]
            path_a = os.path.join(weights_dir, base_files[0])
            path_b = os.path.join(weights_dir, base_files[1])

            model_a = self.load_model(arch_a, path_a)
            model_b = self.load_model(arch_b, path_b)

            if "weights" in ensemble_info and isinstance(ensemble_info["weights"], dict):
                weight_val = list(ensemble_info["weights"].values())[0]

            ensemble = EnsembleModel(model_a, model_b, weight_val, arch_a, arch_b).to(self.device)
            ensemble.eval()
            logger.info(f"Ensemble assembled from base weights (w_a={weight_val:.2f})")
            return ensemble

        raise RuntimeError(f"Unable to load ensemble model with info: {ensemble_info} and path: {weight_path}")

    def _infer_arch_from_key(self, key: str, models_list: list, index: int) -> str:
        if models_list and len(models_list) > index:
            return models_list[index]
        if "swin" in key.lower():
            return "swin_tiny_patch4_window7_224"
        if "effnet" in key.lower() or "efficientnet" in key.lower():
            return "tf_efficientnetv2_s"
        if "resnext" in key.lower():
            return "resnext50_32x4d"
        if "fnet" in key.lower():
            return "fnet"
        if "perceiver" in key.lower():
            return "perceiver"
        return "tf_efficientnetv2_s"


    def _build_model(self, architecture: str) -> nn.Module:
        if architecture == "fnet":
            model = build_fnet(num_classes=NUM_CLASSES)
            logger.info("Built custom FNet architecture")
            return model

        if architecture == "perceiver":
            model = build_perceiver(num_classes=NUM_CLASSES)
            logger.info("Built custom Perceiver architecture")
            return model

        available = timm.list_models()
        if architecture not in available:
            raise ValueError(
                f"Architecture '{architecture}' is not a valid timm model "
                f"and is not a supported custom architecture."
            )

        img_size_supported = {
            "swin_tiny_patch4_window7_224",
            "tf_efficientnetv2_s",
            "resnext50_32x4d",
            "resnet50",
        }

        if architecture in img_size_supported:
            try:
                model = timm.create_model(
                    architecture, pretrained=False,
                    num_classes=NUM_CLASSES, img_size=IMAGE_SIZE,
                )
                logger.info(f"Built {architecture} with img_size={IMAGE_SIZE}")
                return model
            except TypeError:
                logger.warning(f"{architecture} does not accept img_size — building without it.")

        model = timm.create_model(architecture, pretrained=False, num_classes=NUM_CLASSES)
        logger.info(f"Built {architecture} (no img_size)")
        return model

    def _load_weights(self, model: nn.Module, weight_path: str) -> nn.Module:
        try:
            checkpoint = torch.load(weight_path, map_location=self.device, weights_only=True)
        except Exception as e:
            logger.warning(f"weights_only=True failed ({e}). Retrying with weights_only=False.")
            try:
                checkpoint = torch.load(weight_path, map_location=self.device, weights_only=False)
            except Exception as e2:
                logger.error(f"Weight loading error: {e2}")
                raise RuntimeError(f"Failed to load weights: {e2}") from e2

        if isinstance(checkpoint, dict):
            if "model_state_dict" in checkpoint:
                state_dict = checkpoint["model_state_dict"]
            elif "state_dict" in checkpoint:
                state_dict = checkpoint["state_dict"]
            else:
                state_dict = checkpoint
            state_dict          = self._clean_state_dict(state_dict)
            missing, unexpected = model.load_state_dict(state_dict, strict=False)
            if missing:   logger.warning(f"Missing keys   : {len(missing)}")
            if unexpected: logger.warning(f"Unexpected keys: {len(unexpected)}")
        else:
            model = checkpoint

        logger.info(f"Weights loaded: {os.path.basename(weight_path)}")
        return model

    def _clean_state_dict(self, state_dict: dict) -> dict:
        return {k.replace("module.", ""): v for k, v in state_dict.items()}

    def get_device(self):  return self.device
    def get_classes(self): return CLASSES

