# spectrum/wavelength_manager.py - Wavelength Metadata Manager
# ============================================================

import numpy as np
from loguru import logger


class WavelengthManager:
    """
    Manages and validates wavelength metadata (nm) for hyperspectral cubes.
    Enforces strict equality: len(wavelengths) == number_of_bands.
    """

    def __init__(self, wavelengths: np.ndarray | list | None = None):
        self.wavelengths: np.ndarray | None = None
        if wavelengths is not None:
            self.set_wavelengths(wavelengths)

    def set_wavelengths(self, wavelengths: np.ndarray | list) -> None:
        arr = np.array(wavelengths, dtype=np.float64).flatten()
        if len(arr) == 0:
            raise ValueError("Wavelength array cannot be empty.")
        self.wavelengths = arr

    def validate_for_cube(self, num_bands: int) -> bool:
        """
        Validates whether the current wavelength array matches the cube band count.
        """
        if self.wavelengths is None:
            return False
        if len(self.wavelengths) != num_bands:
            logger.error(
                f"Wavelength band mismatch: len(wavelengths)={len(self.wavelengths)} "
                f"!= num_bands={num_bands}"
            )
            return False
        return True

    def get_range_str(self) -> str:
        """Returns string representation of wavelength range (e.g. '')."""
        if self.wavelengths is None or len(self.wavelengths) == 0:
            return "Not available"
        return f"{self.wavelengths[0]:.1f} - {self.wavelengths[-1]:.1f} nm"

    def get_wavelength(self, band_idx: int) -> float | None:
        if self.wavelengths is None or band_idx < 0 or band_idx >= len(self.wavelengths):
            return None
        return float(self.wavelengths[band_idx])

    def peak_wavelength(self, spectrum: np.ndarray) -> float | None:
        """Find dominant wavelength corresponding to peak intensity."""
        if self.wavelengths is None or spectrum is None or len(spectrum) != len(self.wavelengths):
            return None
        idx = int(np.argmax(spectrum))
        return float(self.wavelengths[idx])

    def spectral_category(self, wavelength_nm: float) -> str:
        """Categorize wavelength into UV, Visible spectrum color, or IR."""
        if wavelength_nm < 380:
            return "Ultraviolet (UV)"
        elif wavelength_nm < 450:
            return "Violet (380-450 nm)"
        elif wavelength_nm < 495:
            return "Blue (450-495 nm)"
        elif wavelength_nm < 570:
            return "Green (495-570 nm)"
        elif wavelength_nm < 590:
            return "Yellow (570-590 nm)"
        elif wavelength_nm < 620:
            return "Orange (590-620 nm)"
        elif wavelength_nm < 750:
            return "Red (620-750 nm)"
        else:
            return "Infrared (IR)"


