# ============================================================
# HYPERLUMA + SPECTRUM Integration
# spectrum/roi_selector.py - ROI Tools & Coordinate Mapping
# ============================================================

import enum
import numpy as np
import cv2
from loguru import logger


class ROIType(enum.Enum):
    NONE = "none"
    RECTANGLE = "rectangle"
    CIRCLE = "circle"
    # Compatibility aliases
    PIXEL = "rectangle"
    POLYGON = "circle"


class ROIItem:
    """Represents a single selected Region of Interest (ROI)."""

    def __init__(
        self,
        roi_type: ROIType,
        points: list[tuple[int, int]],
        mask: np.ndarray,
        color: tuple[int, int, int] = (0, 200, 255),
        label: str = "ROI",
    ):
        self.roi_type = roi_type
        self.points = points
        self.mask = mask  # Boolean 2D mask (H, W)
        self.color = color  # BGR color tuple
        self.label = label

    @property
    def pixel_count(self) -> int:
        if self.mask is None:
            return 0
        return int(np.sum(self.mask))

    @property
    def bounds(self) -> tuple[int, int, int, int] | None:
        """Returns (min_x, min_y, max_x, max_y) bounding box."""
        if self.mask is None or not np.any(self.mask):
            return None
        ys, xs = np.where(self.mask)
        return int(np.min(xs)), int(np.min(ys)), int(np.max(xs)), int(np.max(ys))


class ROISelector:
    """
    Manages ROI tool modes, interactive drawing points, coordinate mapping between
    display widgets, original images, and HSI data cubes, and mask generation.
    """

    def __init__(self):
        self.current_tool = ROIType.RECTANGLE
        self.current_points: list[tuple[int, int]] = []
        self.is_drawing = False
        self.roi_counter = 1
        self.color_palette = [
            (0, 200, 255),   # Bright Cyan/Yellow
            (255, 140, 0),   # Bright Blue/Orange
            (50, 205, 50),   # Lime Green
            (220, 20, 60),   # Crimson Red
            (186, 85, 211),  # Medium Orchid
            (255, 215, 0),   # Gold
        ]

    def set_tool(self, tool: ROIType) -> None:
        self.current_tool = tool
        self.reset_current_drawing()

    def reset_current_drawing(self) -> None:
        self.current_points.clear()
        self.is_drawing = False

    def add_point(self, pt: tuple[int, int]) -> None:
        self.current_points.append(pt)

    def generate_mask(self, cube_h: int, cube_w: int) -> np.ndarray | None:
        """
        Generates a 2D boolean mask of shape (cube_h, cube_w) for the active points.
        """
        if not self.current_points or cube_h <= 0 or cube_w <= 0:
            return None

        mask = np.zeros((cube_h, cube_w), dtype=bool)

        if self.current_tool == ROIType.RECTANGLE:
            if len(self.current_points) < 2:
                return None
            x1, y1 = self.current_points[0]
            x2, y2 = self.current_points[1]
            min_x, max_x = sorted((x1, x2))
            min_y, max_y = sorted((y1, y2))

            min_x = max(0, min(min_x, cube_w - 1))
            max_x = max(0, min(max_x, cube_w - 1))
            min_y = max(0, min(min_y, cube_h - 1))
            max_y = max(0, min(max_y, cube_h - 1))

            mask[min_y:max_y + 1, min_x:max_x + 1] = True
            return mask

        elif self.current_tool == ROIType.CIRCLE:
            if len(self.current_points) < 2:
                return None
            x1, y1 = self.current_points[0]
            x2, y2 = self.current_points[1]
            min_x, max_x = sorted((x1, x2))
            min_y, max_y = sorted((y1, y2))

            min_x = max(0, min(min_x, cube_w - 1))
            max_x = max(0, min(max_x, cube_w - 1))
            min_y = max(0, min(min_y, cube_h - 1))
            max_y = max(0, min(max_y, cube_h - 1))

            center_x = (min_x + max_x) // 2
            center_y = (min_y + max_y) // 2
            axis_x = max(1, (max_x - min_x) // 2)
            axis_y = max(1, (max_y - min_y) // 2)

            circ_img = np.zeros((cube_h, cube_w), dtype=np.uint8)
            cv2.ellipse(circ_img, (center_x, center_y), (axis_x, axis_y), 0, 0, 360, 1, -1)
            return circ_img.astype(bool)

        return None

    def create_roi_item(self, cube_h: int, cube_w: int) -> ROIItem | None:
        mask = self.generate_mask(cube_h, cube_w)
        if mask is None or not np.any(mask):
            return None

        color = self.color_palette[(self.roi_counter - 1) % len(self.color_palette)]
        label = f"ROI {self.roi_counter} ({self.current_tool.value.capitalize()})"
        self.roi_counter += 1

        roi = ROIItem(
            roi_type=self.current_tool,
            points=list(self.current_points),
            mask=mask,
            color=color,
            label=label,
        )
        self.reset_current_drawing()
        return roi

    @staticmethod
    def map_display_to_image_coords(
        disp_x: float,
        disp_y: float,
        widget_w: int,
        widget_h: int,
        img_w: int,
        img_h: int,
    ) -> tuple[int, int]:
        """
        Maps widget display coordinates to actual underlying image matrix coordinates,
        accounting for aspect-ratio preservation scaling and letterbox margins.
        """
        if widget_w <= 0 or widget_h <= 0 or img_w <= 0 or img_h <= 0:
            return 0, 0

        scale = min(widget_w / img_w, widget_h / img_h)
        scaled_w = img_w * scale
        scaled_h = img_h * scale

        offset_x = (widget_w - scaled_w) / 2.0
        offset_y = (widget_h - scaled_h) / 2.0

        img_x = int((disp_x - offset_x) / scale)
        img_y = int((disp_y - offset_y) / scale)

        img_x = max(0, min(img_x, img_w - 1))
        img_y = max(0, min(img_y, img_h - 1))
        return img_x, img_y

    @staticmethod
    def map_image_to_cube_coords(
        img_x: int,
        img_y: int,
        img_w: int,
        img_h: int,
        cube_w: int,
        cube_h: int,
    ) -> tuple[int, int]:
        """
        Maps image pixel coordinates to spectral cube spatial grid indices.
        """
        if img_w <= 0 or img_h <= 0 or cube_w <= 0 or cube_h <= 0:
            return 0, 0

        scale_x = cube_w / img_w
        scale_y = cube_h / img_h

        cube_x = int(img_x * scale_x)
        cube_y = int(img_y * scale_y)

        cube_x = max(0, min(cube_x, cube_w - 1))
        cube_y = max(0, min(cube_y, cube_h - 1))
        return cube_x, cube_y


