# spectrum/spectral_extractor.py - Spectral Value Extractor
# ============================================================

import cv2
import numpy as np
from loguru import logger
# [Bundled] from .roi_selector import ROIItem, ROIType


class SpectralExtractor:
    """
    Extracts spectral signatures, mean spectra, and standard deviation
    from HSI data cubes based on spatial ROI masks.
    """

    @staticmethod
    def extract_pixel_spectrum(cube: np.ndarray, x: int, y: int) -> np.ndarray | None:
        """
        Extracts spectral curve for a single pixel (x, y).
        Returns array of shape (Bands,).
        """
        if cube is None or cube.ndim != 3:
            return None
        h, w, b = cube.shape
        if not (0 <= x < w and 0 <= y < h):
            logger.warning(f"Pixel ({x}, {y}) out of cube bounds ({w}x{h})")
            return None
        return cube[y, x, :].astype(np.float64)

    @staticmethod
    def extract_roi_spectrum(
        cube: np.ndarray,
        roi: ROIItem,
    ) -> tuple[np.ndarray | None, np.ndarray | None, dict]:
        """
        Extracts mean spectrum and standard deviation for the given ROI.
        Returns:
            mean_spectrum: (Bands,) array or None
            std_spectrum: (Bands,) array or None
            stats_info: Dictionary containing metadata and statistics
        """
        stats_info = {
            "label": roi.label if roi else "Unknown",
            "type": roi.roi_type.value if roi else "Unknown",
            "pixel_count": 0,
            "mean_val": 0.0,
            "min_val": 0.0,
            "max_val": 0.0,
            "has_std": False,
        }

        if cube is None or cube.ndim != 3 or roi is None or roi.mask is None:
            return None, None, stats_info

        h, w, bands = cube.shape
        mask = roi.mask

        if mask.shape[0] != h or mask.shape[1] != w:
            # Resize mask if cube and mask dimensions differ slightly
            mask_uint = cv2.resize(mask.astype(np.uint8), (w, h), interpolation=cv2.INTER_NEAREST)
            mask = mask_uint.astype(bool)

        if not np.any(mask):
            return None, None, stats_info

        # Extract all spatial pixels matching the ROI mask -> shape (N_pixels, Bands)
        selected_pixels = cube[mask]
        num_pixels = selected_pixels.shape[0]

        mean_spec = np.mean(selected_pixels, axis=0).astype(np.float64)

        if num_pixels > 1:
            std_spec = np.std(selected_pixels, axis=0).astype(np.float64)
            has_std = True
        else:
            std_spec = np.zeros_like(mean_spec)
            has_std = False

        stats_info.update({
            "pixel_count": num_pixels,
            "mean_val": float(np.mean(mean_spec)),
            "min_val": float(np.min(mean_spec)),
            "max_val": float(np.max(mean_spec)),
            "has_std": has_std,
            "bounds": roi.bounds,
        })

        return mean_spec, std_spec, stats_info


