# spectrum/disease_band_manager.py
# Reads disease wavelength bands from BandSelection_RetinaSixClasses_Update.xlsx
# and provides dynamic disease mapping and color assignment.

import os
import openpyxl
from loguru import logger

# FIXED DISEASE COLORS (Do not change per user requirements)
DISEASE_COLORS = {
    "AMD": "#DC2626",        # RED
    "Cataract": "#CA8A04",   # YELLOW / AMBER (high contrast on white)
    "Dementia": "#7C3AED",   # PURPLE
    "Diabetes": "#EA580C",   # ORANGE
    "Glaucoma": "#2563EB",   # BLUE
    "Normal": "#16A34A",     # GREEN
    "No Match": "#718096",   # NEUTRAL GRAY
}

FALLBACK_MAPPING = {
    "AMD": (580.0, 620.0),
    "Cataract": (450.0, 490.0),
    "Dementia": (740.0, 750.0),
    "Diabetes": (550.0, 575.0),
    "Glaucoma": (700.0, 720.0),
}


class DiseaseBandManager:
    """
    Loads disease wavelength bands from BandSelection_RetinaSixClasses_Update.xlsx
    and evaluates which disease(s) correspond to a given wavelength or band range.
    """
    _instance = None

    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._initialized = False
        return cls._instance

    def __init__(self, excel_path: str | None = None):
        if self._initialized:
            return
        self.excel_path = self._find_excel_file(excel_path)
        self.disease_bands: dict[str, tuple[float, float]] = {}
        self.load_bands()
        self._initialized = True

    def _find_excel_file(self, explicit_path: str | None = None) -> str | None:
        if explicit_path and os.path.isfile(explicit_path):
            return os.path.abspath(explicit_path)

        filename = "BandSelection_RetinaSixClasses_Update.xlsx"
        candidates = [
            os.path.join(os.getcwd(), filename),
            os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "..", filename)),
            os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "..", "..", filename)),
            r"c:\Users\Asus\OneDrive\Desktop\AI-EYE DISEASE\AI-Based_Eye_Disease_Detection-main\AI-Based_Eye_Disease_Detection-main\BandSelection_RetinaSixClasses_Update.xlsx",
        ]
        for path in candidates:
            if os.path.isfile(path):
                return os.path.abspath(path)
        return None

    def load_bands(self) -> dict[str, tuple[float, float]]:
        """
        Loads the disease wavelength bands directly from the Excel file.
        Uses sheet 'SD' (Band Selection) and sheet 'All_Diseases1'.
        """
        if not self.excel_path or not os.path.isfile(self.excel_path):
            logger.warning(f"Excel file not found, using default workbook values: {FALLBACK_MAPPING}")
            self.disease_bands = dict(FALLBACK_MAPPING)
            return self.disease_bands

        try:
            wb = openpyxl.load_workbook(self.excel_path, data_only=True)
            
            # Read bands from sheet 'SD' under 'Band Selection'
            bands = []
            if "SD" in wb.sheetnames:
                ws_sd = wb["SD"]
                for r in range(1, ws_sd.max_row + 1):
                    for c in range(1, ws_sd.max_column + 1):
                        val = ws_sd.cell(r, c).value
                        if val and "band selection" in str(val).lower():
                            for offset in range(1, 20):
                                b_cell = ws_sd.cell(r + offset, c).value
                                if b_cell and "-" in str(b_cell):
                                    bands.append(str(b_cell).strip())
                                else:
                                    break
                            break
                    if bands:
                        break

            # Read disease names from 'All_Diseases1'
            diseases = []
            if "All_Diseases1" in wb.sheetnames:
                ws_dis = wb["All_Diseases1"]
                for c in range(1, ws_dis.max_column + 1):
                    val = ws_dis.cell(1, c).value
                    if val and isinstance(val, str) and val.strip():
                        diseases.append(val.strip())

            if not diseases:
                diseases = ["AMD", "Cataract", "Dementia", "Diabetes", "Glaucoma"]

            parsed_mapping = {}
            for d, b in zip(diseases, bands):
                parts = b.split("-")
                try:
                    min_w, max_w = float(parts[0]), float(parts[1])
                    parsed_mapping[d] = (min_w, max_w)
                except Exception as e:
                    logger.warning(f"Could not parse band '{b}' for {d}: {e}")

            # Also check if Normal sheet has any band range
            if "Normal" in wb.sheetnames:
                ws_norm = wb["Normal"]
                for r in range(1, 10):
                    for c in range(1, ws_norm.max_column + 1):
                        v = ws_norm.cell(r, c).value
                        if v and isinstance(v, str) and "-" in v and any(ch.isdigit() for ch in v):
                            parts = v.split("-")
                            try:
                                parsed_mapping["Normal"] = (float(parts[0]), float(parts[1]))
                            except Exception:
                                pass

            if parsed_mapping:
                self.disease_bands = parsed_mapping
                logger.info(f"Successfully loaded disease bands from {self.excel_path}: {self.disease_bands}")
            else:
                self.disease_bands = dict(FALLBACK_MAPPING)

        except Exception as exc:
            logger.error(f"Error reading Excel {self.excel_path}: {exc}")
            self.disease_bands = dict(FALLBACK_MAPPING)

        return self.disease_bands

    def match_wavelength(self, wavelength: float) -> list[tuple[str, str, tuple[float, float]]]:
        """
        Returns all diseases whose wavelength band contains the given wavelength.
        Returns list of (disease_name, color_hex, (min_wl, max_wl)).
        """
        matches = []
        for disease, (min_wl, max_wl) in self.disease_bands.items():
            # Range check inclusive: min_wl <= wavelength <= max_wl
            if min_wl <= wavelength <= max_wl:
                color = DISEASE_COLORS.get(disease, "#2563EB")
                matches.append((disease, color, (min_wl, max_wl)))
        return matches

    def match_band_range(self, min_wl: float, max_wl: float) -> list[tuple[str, str, tuple[float, float]]]:
        """
        Returns all diseases whose wavelength band overlaps with [min_wl, max_wl].
        """
        matches = []
        for disease, (d_min, d_max) in self.disease_bands.items():
            # Check overlap: max(start1, start2) <= min(end1, end2)
            if max(min_wl, d_min) <= min(max_wl, d_max):
                color = DISEASE_COLORS.get(disease, "#2563EB")
                matches.append((disease, color, (d_min, d_max)))
        return matches


