# spectrum/disease_band_indicator.py
# Dynamic disease indicator widget placed underneath the spectral graph.

import sys
try:
    from PyQt5.QtCore import Qt
    from PyQt5.QtGui import QFont
    from PyQt5.QtWidgets import QWidget, QHBoxLayout, QVBoxLayout, QLabel, QFrame
    ALIGN_CENTER = Qt.AlignCenter
    ALIGN_LEFT = Qt.AlignLeft
except ImportError:
    from PyQt6.QtCore import Qt
    from PyQt6.QtGui import QFont
    from PyQt6.QtWidgets import QWidget, QHBoxLayout, QVBoxLayout, QLabel, QFrame
    ALIGN_CENTER = Qt.AlignmentFlag.AlignCenter
    ALIGN_LEFT = Qt.AlignmentFlag.AlignLeft

# [Bundled] from spectrum.disease_band_manager import DiseaseBandManager, DISEASE_COLORS


class DiseaseBandIndicatorWidget(QFrame):
    """
    Dynamic indicator widget displayed directly underneath the spectral graph.
    Shows the active disease(s) and assigned fixed colors corresponding to
    the current graph wavelength or selected band.
    """

    def __init__(self, parent=None):
        super().__init__(parent)
        self.band_mgr = DiseaseBandManager()
        self.current_wavelength: float | None = None
        self.current_band_range: tuple[float, float] | None = None

        self._init_ui()
        self.reset()

    def _init_ui(self):
        self.setFrameShape(QFrame.StyledPanel if hasattr(QFrame, "StyledPanel") else QFrame.Shape.StyledPanel)
        self.setStyleSheet("""
            DiseaseBandIndicatorWidget {
                background-color: #F8FAFC;
                border: 1px solid #CBD5E0;
                border-radius: 6px;
                padding: 4px 10px;
            }
        """)

        # Main horizontal layout
        self.main_layout = QHBoxLayout(self)
        self.main_layout.setContentsMargins(6, 4, 6, 4)
        self.main_layout.setSpacing(12)

        # Current Wavelength Badge / Label
        self.wl_badge = QLabel("Wavelength: — nm")
        self.wl_badge.setStyleSheet("""
            QLabel {
                color: #1A2B4A;
                font-weight: bold;
                font-size: 8.5pt;
                background-color: #EDF2F7;
                border: 1px solid #CBD5E0;
                border-radius: 4px;
                padding: 2px 6px;
            }
        """)
        self.main_layout.addWidget(self.wl_badge)

        # Dynamic items container
        self.items_container = QWidget()
        self.items_container.setStyleSheet("background: transparent;")
        self.items_layout = QHBoxLayout(self.items_container)
        self.items_layout.setContentsMargins(0, 0, 0, 0)
        self.items_layout.setSpacing(14)
        self.items_layout.setAlignment(ALIGN_LEFT | Qt.AlignVCenter if hasattr(Qt, "AlignVCenter") else ALIGN_LEFT | Qt.AlignmentFlag.AlignVCenter)

        self.main_layout.addWidget(self.items_container, stretch=1)

    def reset(self):
        """Reset indicator to neutral state (No specific disease band)."""
        self.current_wavelength = None
        self.current_band_range = None
        self.wl_badge.setText("Wavelength: — nm")
        self._display_no_match()

    def update_for_wavelength(self, wl: float):
        """Update indicator for a specific graph wavelength (nm)."""
        if wl is None:
            self.reset()
            return

        self.current_wavelength = wl
        self.current_band_range = None
        self.wl_badge.setText(f"Wavelength: {wl:.1f} nm")

        matches = self.band_mgr.match_wavelength(wl)
        if matches:
            self._display_matches(matches)
        else:
            self._display_no_match()

    def update_for_band_range(self, min_wl: float, max_wl: float, label: str = ""):
        """Update indicator when a band range is selected in the UI."""
        if min_wl is None or max_wl is None:
            self.reset()
            return

        self.current_wavelength = (min_wl + max_wl) / 2.0
        self.current_band_range = (min_wl, max_wl)
        self.wl_badge.setText(f"Band: {min_wl:.0f} - {max_wl:.0f} nm")

        matches = self.band_mgr.match_band_range(min_wl, max_wl)
        if matches:
            self._display_matches(matches)
        else:
            self._display_no_match()

    def _clear_items(self):
        """Removes all dynamic item widgets immediately."""
        while self.items_layout.count():
            item = self.items_layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.setParent(None)
                widget.deleteLater()

    def _display_matches(self, matches: list[tuple[str, str, tuple[float, float]]]):
        """
        Renders matching diseases using their fixed assigned color:
        ━━━━━━━━ AMD
        """
        self._clear_items()
        for disease, color, (d_min, d_max) in matches:
            item_lbl = QLabel(f"━━━━━━━━  {disease}")
            item_lbl.setStyleSheet(f"""
                QLabel {{
                    color: {color};
                    font-weight: bold;
                    font-size: 9.5pt;
                    background: transparent;
                }}
            """)
            item_lbl.setToolTip(f"{disease} Band: {d_min:.0f} - {d_max:.0f} nm")
            self.items_layout.addWidget(item_lbl)

    def _display_no_match(self):
        """Displays '━━━━━━━━ No specific disease band' in neutral gray."""
        self._clear_items()
        gray_color = DISEASE_COLORS.get("No Match", "#718096")
        no_match_lbl = QLabel("━━━━━━━━  No specific disease band")
        no_match_lbl.setStyleSheet(f"""
            QLabel {{
                color: {gray_color};
                font-weight: bold;
                font-size: 9pt;
                background: transparent;
            }}
        """)
        self.items_layout.addWidget(no_match_lbl)


