# HYPERLUMA + SPECTRUM Integration
# spectrum/spectral_disease_mapper.py - Excel-based Spectral Disease Mapper
# ============================================================

import os
import sys
import numpy as np
import pandas as pd
from loguru import logger

# Exact fixed disease color palette requested by user
DISEASE_COLORS = {
    "AMD": "#DC2626",                    # Red
    "Cataract": "#EAB308",               # Yellow (rich amber/yellow)
    "Dementia": "#9333EA",               # Purple
    "Diabetes": "#EA580C",               # Orange
    "Glaucoma": "#2563EB",               # Blue
    "Normal": "#16A34A",                 # Green
    "Non-specific / Overlapping": "#64748B",  # Neutral Gray
}

# Light background tint for cards/badges
DISEASE_BG_COLORS = {
    "AMD": "#FEF2F2",
    "Cataract": "#FEFCE8",
    "Dementia": "#FAF5FF",
    "Diabetes": "#FFF7ED",
    "Glaucoma": "#EFF6FF",
    "Normal": "#F0FDF4",
    "Non-specific / Overlapping": "#F1F5F9",
}

# Border color for cards/badges
DISEASE_BORDER_COLORS = {
    "AMD": "#FCA5A5",
    "Cataract": "#FDE047",
    "Dementia": "#D8B4FE",
    "Diabetes": "#FDBA74",
    "Glaucoma": "#93C5FD",
    "Normal": "#86EFAC",
    "Non-specific / Overlapping": "#CBD5E1",
}


class SpectralDiseaseMapper:
    """
    Loads spectral response data from BandSelection_RetinaSixClasses_Update.xlsx
    and dynamically associates wavelengths / bands with disease classes.
    """

    _instance = None

    @classmethod
    def get_instance(cls):
        if cls._instance is None:
            cls._instance = SpectralDiseaseMapper()
        return cls._instance

    def __init__(self, excel_path: str | None = None):
        self.excel_path = excel_path or self._locate_excel()
        self.raw_df: pd.DataFrame | None = None
        self.score_df: pd.DataFrame | None = None
        self.wavelengths: np.ndarray | None = None
        self.disease_cols = [
            "Avg_AMD",
            "Avg_Cataract",
            "Avg_Dementia",
            "Avg_Diabetes",
            "Avg_Glaucoma",
            "Avg_Normal",
        ]
        self.class_names = ["AMD", "Cataract", "Dementia", "Diabetes", "Glaucoma", "Normal"]
        # Margin threshold below which classification is considered Non-specific / Overlapping
        self._margin_threshold = 0.025
        self._load_data()

    def _locate_excel(self) -> str | None:
        filename = "BandSelection_RetinaSixClasses_Update.xlsx"
        possible_dirs = [
            os.getcwd(),
            os.path.dirname(os.path.abspath(__file__)),
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
            os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))),
            r"c:\Users\Asus\OneDrive\Desktop\AI-EYE DISEASE\AI-Based_Eye_Disease_Detection-main\AI-Based_Eye_Disease_Detection-main",
        ]
        for d in possible_dirs:
            p = os.path.join(d, filename)
            if os.path.isfile(p):
                logger.info(f"Located Excel spectral dataset at: {p}")
                return p
        logger.warning(f"Could not locate {filename} in known paths.")
        return None

    def _load_data(self):
        if not self.excel_path or not os.path.isfile(self.excel_path):
            logger.warning("SpectralDiseaseMapper: No valid Excel path found. Mapper will run in fallback mode.")
            return

        try:
            d1 = pd.read_excel(self.excel_path, sheet_name="All_Diseases1", header=1)
            d2 = pd.read_excel(self.excel_path, sheet_name="Normal", header=1)

            cols_d1 = ["Bands", "Avg_AMD", "Avg_Cataract", "Avg_Dementia", "Avg_Diabetes", "Avg_Glaucoma"]
            cols_d2 = ["Bands", "Avg_Normal"]

            merged = pd.merge(d1[cols_d1], d2[cols_d2], on="Bands")
            merged = merged.sort_values("Bands").reset_index(drop=True)

            self.raw_df = merged
            self.wavelengths = merged["Bands"].values.astype(float)

            # Standardized Spectral Signatures (Z-score standardization per disease across )
            # This balances baseline illuminance offsets and measures the distinctive deviation
            # of each disease at every specific wavelength.
            scores = (merged[self.disease_cols] - merged[self.disease_cols].mean(axis=0)) / merged[self.disease_cols].std(axis=0)
            scores["Bands"] = merged["Bands"]
            self.score_df = scores

            logger.info(f"SpectralDiseaseMapper: Loaded {len(self.raw_df)} bands ({self.wavelengths[0]:.0f} - {self.wavelengths[-1]:.0f} nm)")
        except Exception as exc:
            logger.error(f"SpectralDiseaseMapper failed to load Excel data: {exc}")

    def get_disease_for_wavelength(self, wavelength_nm: float) -> dict:
        """
        Determines the disease with the strongest/most distinctive spectral response
        at a specific wavelength (nm).
        Returns a dict with:
            - wavelength: float
            - display_wl_str: str
            - disease: str
            - color: str (hex)
            - bg_color: str (hex)
            - border_color: str (hex)
            - is_overlapping: bool
            - winner_name: str
            - winner_value: float
            - runner_up: str
            - runner_up_value: float
            - margin: float
            - responses: dict
        """
        if self.score_df is None or self.wavelengths is None:
            return self._fallback_response(wavelength_nm)

        # Find closest wavelength row
        idx = int(np.argmin(np.abs(self.wavelengths - wavelength_nm)))
        actual_wl = float(self.wavelengths[idx])

        row_vals = {
            col.replace("Avg_", ""): float(self.score_df.loc[idx, col])
            for col in self.disease_cols
        }

        sorted_responses = sorted(row_vals.items(), key=lambda x: x[1], reverse=True)
        winner_name, winner_val = sorted_responses[0]
        runner_up_name, runner_up_val = sorted_responses[1]
        margin = winner_val - runner_up_val

        is_overlapping = margin < self._margin_threshold
        final_disease = "Non-specific / Overlapping" if is_overlapping else winner_name

        return {
            "wavelength": actual_wl,
            "display_wl_str": f"{actual_wl:.0f} nm" if abs(actual_wl - round(actual_wl)) < 0.1 else f"{actual_wl:.1f} nm",
            "disease": final_disease,
            "color": DISEASE_COLORS.get(final_disease, "#64748B"),
            "bg_color": DISEASE_BG_COLORS.get(final_disease, "#F1F5F9"),
            "border_color": DISEASE_BORDER_COLORS.get(final_disease, "#CBD5E1"),
            "is_overlapping": is_overlapping,
            "winner_name": winner_name,
            "winner_value": winner_val,
            "runner_up": runner_up_name,
            "runner_up_value": runner_up_val,
            "margin": margin,
            "responses": row_vals,
        }

    def get_disease_for_range(self, min_wl: float, max_wl: float) -> dict:
        """
        Determines the disease with the strongest/most distinctive spectral response
        averaged across a band range [min_wl, max_wl].
        """
        if self.score_df is None or self.wavelengths is None:
            avg_wl = (min_wl + max_wl) / 2.0
            return self._fallback_response(avg_wl, range_str=f"{min_wl:.0f} - {max_wl:.0f} nm")

        mask = (self.score_df["Bands"] >= min_wl) & (self.score_df["Bands"] <= max_wl)
        sub = self.score_df.loc[mask, self.disease_cols]

        if sub.empty:
            return self.get_disease_for_wavelength((min_wl + max_wl) / 2.0)

        mean_vals = sub.mean(axis=0)
        row_vals = {
            col.replace("Avg_", ""): float(mean_vals[col])
            for col in self.disease_cols
        }

        sorted_responses = sorted(row_vals.items(), key=lambda x: x[1], reverse=True)
        winner_name, winner_val = sorted_responses[0]
        runner_up_name, runner_up_val = sorted_responses[1]
        margin = winner_val - runner_up_val

        is_overlapping = margin < self._margin_threshold
        final_disease = "Non-specific / Overlapping" if is_overlapping else winner_name
        avg_wl = float((min_wl + max_wl) / 2.0)

        return {
            "wavelength": avg_wl,
            "range": (min_wl, max_wl),
            "display_wl_str": f"{min_wl:.0f} - {max_wl:.0f} nm (Avg {avg_wl:.0f} nm)",
            "disease": final_disease,
            "color": DISEASE_COLORS.get(final_disease, "#64748B"),
            "bg_color": DISEASE_BG_COLORS.get(final_disease, "#F1F5F9"),
            "border_color": DISEASE_BORDER_COLORS.get(final_disease, "#CBD5E1"),
            "is_overlapping": is_overlapping,
            "winner_name": winner_name,
            "winner_value": winner_val,
            "runner_up": runner_up_name,
            "runner_up_value": runner_up_val,
            "margin": margin,
            "responses": row_vals,
        }

    def _fallback_response(self, wl: float, range_str: str | None = None) -> dict:
        return {
            "wavelength": wl,
            "display_wl_str": range_str if range_str else f"{wl:.0f} nm",
            "disease": "Non-specific / Overlapping",
            "color": DISEASE_COLORS["Non-specific / Overlapping"],
            "bg_color": DISEASE_BG_COLORS["Non-specific / Overlapping"],
            "border_color": DISEASE_BORDER_COLORS["Non-specific / Overlapping"],
            "is_overlapping": True,
            "winner_name": "Unknown",
            "winner_value": 0.0,
            "runner_up": "Unknown",
            "runner_up_value": 0.0,
            "margin": 0.0,
            "responses": {},
        }


