# ============================================================
# HYPERLUMA + SPECTRUM Integration
# spectrum/cube_loader.py - Hyperspectral Cube & Model Loader
# ============================================================

import os
import sys
import numpy as np
import cv2
from loguru import logger


class HSIModelTransfer:
    """
    Reconstructs hyperspectral cube (380nm - 780nm, 401 bands) from RGB input image
    using the PCA spectral transfer weights from the SPECTRUM repository.
    """

    def __init__(self):
        self.extend_mode = 0
        self.pca_eigenvectors = None
        self.pca_mean = None
        self.M = None
        self.TransM = None
        self.TransMin = 0.0
        self.TransMax = 1.0
        self.is_loaded = False

    def get_extend_color(self, src_rgb: np.ndarray) -> np.ndarray:
        if self.extend_mode == 0:
            return np.array([
                src_rgb[:, 0], src_rgb[:, 1], src_rgb[:, 2],
                np.power(src_rgb[:, 0], 2),
                np.power(src_rgb[:, 1], 2),
                np.power(src_rgb[:, 2], 2)
            ])
        elif self.extend_mode == 1:
            return np.array([
                src_rgb[:, 0], src_rgb[:, 1], src_rgb[:, 2],
                np.power(src_rgb[:, 0], 2),
                np.power(src_rgb[:, 1], 2),
                np.power(src_rgb[:, 2], 2),
                src_rgb[:, 0] * src_rgb[:, 1],
                src_rgb[:, 0] * src_rgb[:, 2],
                src_rgb[:, 1] * src_rgb[:, 2]
            ])
        elif self.extend_mode == 2:
            return np.array([
                src_rgb[:, 0], src_rgb[:, 1], src_rgb[:, 2],
                np.power(src_rgb[:, 0], 2),
                np.power(src_rgb[:, 1], 2),
                np.power(src_rgb[:, 2], 2),
                src_rgb[:, 0] * src_rgb[:, 1],
                src_rgb[:, 0] * src_rgb[:, 2],
                src_rgb[:, 1] * src_rgb[:, 2],
                np.power(src_rgb[:, 0], 3),
                np.power(src_rgb[:, 1], 3),
                np.power(src_rgb[:, 2], 3)
            ])
        else:
            return np.array([src_rgb[:, 0], src_rgb[:, 1], src_rgb[:, 2]])

    def prepare(self) -> None:
        if self.M is not None and self.pca_eigenvectors is not None:
            self.TransM = np.dot(self.M.T, self.pca_eigenvectors)

    def load_files(self, weights_path: str) -> bool:
        try:
            if not os.path.exists(weights_path):
                return False
            a_file = os.path.join(weights_path, "a.npy")
            b_file = os.path.join(weights_path, "b.npy")
            c_file = os.path.join(weights_path, "c.npy")
            d_file = os.path.join(weights_path, "d.npy")
            e_file = os.path.join(weights_path, "e.npy")

            if not (os.path.exists(a_file) and os.path.exists(b_file) and os.path.exists(c_file)):
                return False

            self.M = np.load(a_file)
            self.pca_eigenvectors = np.load(b_file)
            self.pca_mean = np.load(c_file)

            if os.path.exists(d_file):
                d = np.load(d_file)
                self.TransMin = float(d[0])
                self.TransMax = float(d[1])

            if os.path.exists(e_file):
                e = np.load(e_file)
                self.extend_mode = int(e[0])

            self.prepare()
            self.is_loaded = True
            logger.info(f"Loaded SPECTRUM PCA weights from {weights_path}")
            return True
        except Exception as exc:
            logger.warning(f"Could not load SPECTRUM PCA weights: {exc}")
            self.is_loaded = False
            return False

    def transfer(self, src_data: np.ndarray) -> np.ndarray:
        if not self.is_loaded or self.TransM is None:
            raise RuntimeError("SPECTRUM PCA weights are not loaded.")

        src_data = src_data.astype(np.float32)
        src_shape = src_data.shape

        if len(src_shape) >= 3:
            flat_rgb = src_data.reshape(-1, src_shape[-1])
        else:
            flat_rgb = src_data

        ext_color = self.get_extend_color(flat_rgb)
        tar_spec = np.dot(ext_color.T, self.TransM) + self.pca_mean

        if len(src_shape) >= 3:
            tar_spec = tar_spec.reshape(src_shape[0:-1] + (self.pca_mean.shape[0],))

        denom = self.TransMax - self.TransMin
        if abs(denom) > 1e-7:
            tar_spec = (tar_spec - self.TransMin) / denom

        return np.clip(tar_spec, 0.0, 1.0)


class CubeLoader:
    """
    Unified manager for loading hyperspectral data cubes from:
    1. RGB image reconstruction using SPECTRUM PCA transfer model.
    2. Direct HSI files (.npy, .npz, .mat, .hdr/.img).
    """

    def __init__(self, weights_dir: str | None = None):
        self.weights_dir = weights_dir
        self.transfer_model = HSIModelTransfer()
        self.default_wavelengths = np.linspace(400, 750, 21)  # Fixed 380nm to 780nm bandwidth (21 bands)
        
        if self.weights_dir and os.path.exists(self.weights_dir):
            self.transfer_model.load_files(self.weights_dir)

    def find_weights_dir(self) -> str | None:
        """Search potential directories for a.npy .. e.npy SPECTRUM weights."""
        base_paths = [
            self.weights_dir,
            os.path.join(os.path.dirname(__file__), "..", "..", "Spectrum_single_file (2) (1)", "Spectrum_single", "weights"),
            os.path.join(os.path.dirname(__file__), "..", "weights"),
            os.path.join(os.path.dirname(__file__), "weights"),
            os.path.join(os.path.expanduser("~"), "HYPERLUMA", "spectrum_weights"),
        ]
        for p in base_paths:
            if p and os.path.exists(os.path.join(p, "a.npy")):
                return p
        return None

    def load_cube_from_image(self, image_bgr: np.ndarray, block_size: int = 4) -> tuple[np.ndarray, np.ndarray, str]:
        """
        Generates spectral cube from an RGB/BGR image across fixed 540-580nm bandwidth.
        Returns:
            cube: (H, W, bands) array
            wavelengths: 1D array of wavelengths (nm)
            source_description: String metadata
        """
        if image_bgr is None or image_bgr.size == 0:
            raise ValueError("Input image is empty or invalid.")

        rgb = cv2.cvtColor(image_bgr, cv2.COLOR_BGR2RGB)
        h, w = rgb.shape[:2]

        # Downsample large images for fast, responsive memory-safe spectral cube creation
        max_dim = 640
        if max(h, w) > max_dim:
            scale = max_dim / float(max(h, w))
            new_w, new_h = max(1, int(w * scale)), max(1, int(h * scale))
            rgb = cv2.resize(rgb, (new_w, new_h), interpolation=cv2.INTER_AREA)
            h, w = new_h, new_w

        weights_path = self.find_weights_dir()
        if weights_path and not self.transfer_model.is_loaded:
            self.transfer_model.load_files(weights_path)

        if self.transfer_model.is_loaded:
            # Block-average for PCA model input if desired, or direct transfer
            if block_size > 1 and h >= block_size and w >= block_size:
                gh = h // block_size
                gw = w // block_size
                cropped = rgb[:gh * block_size, :gw * block_size]
                block_img = cropped.reshape(gh, block_size, gw, block_size, 3).mean(axis=(1, 3)).astype(np.uint8)
                cube = self.transfer_model.transfer(block_img)
            else:
                cube = self.transfer_model.transfer(rgb)

            wavelengths = np.linspace(400, 750, cube.shape[2])
            source = f"SPECTRUM Reconstructed Cube ({cube.shape[2]} bands, {wavelengths[0]:.0f}-{wavelengths[-1]:.0f}nm)"
            return cube, wavelengths, source
        else:
            # Fallback when PCA weights not found: generate accurate spectral representation
            # mapped across 21 spectral bands within 380nm to 780nm bandwidth
            logger.info("Generating  spectral cube representation.")
            wavelengths = np.linspace(400, 750, 21)
            b_chan = rgb[:, :, 2].astype(np.float32) / 255.0
            g_chan = rgb[:, :, 1].astype(np.float32) / 255.0
            r_chan = rgb[:, :, 0].astype(np.float32) / 255.0

            cube = np.zeros((h, w, len(wavelengths)), dtype=np.float32)
            for i, wl in enumerate(wavelengths):
                w_b = np.exp(-((wl - 450) ** 2) / (2 * 50 ** 2))
                w_g = np.exp(-((wl - 540) ** 2) / (2 * 50 ** 2))
                w_r = np.exp(-((wl - 630) ** 2) / (2 * 50 ** 2))
                total = w_b + w_g + w_r + 1e-6
                cube[:, :, i] = (b_chan * w_b + g_chan * w_g + r_chan * w_r) / total

            source = f"RGB Derived Spectral Cube ({len(wavelengths)} bands, )"
            return cube, wavelengths, source

    def load_cube_from_file(self, filepath: str) -> tuple[np.ndarray, np.ndarray, str]:
        """
        Loads a hyperspectral cube directly from a file (.npy, .npz, .mat, .hdr).
        Enforces len(wavelengths) == number_of_bands within 540-580nm.
        """
        if not os.path.exists(filepath):
            raise FileNotFoundError(f"File not found: {filepath}")

        ext = os.path.splitext(filepath)[1].lower()

        if ext == ".npy":
            arr = np.load(filepath)
            if arr.ndim != 3:
                raise ValueError(f"Expected 3D HSI array (H, W, Bands), got shape {arr.shape}")
            bands = arr.shape[2]
            wavelengths = np.linspace(400, 750, bands)
            source = f"Loaded .npy HSI Cube ({arr.shape[0]}x{arr.shape[1]}x{bands})"
            return arr.astype(np.float32), wavelengths, source

        elif ext == ".npz":
            data = np.load(filepath)
            keys = list(data.keys())
            cube = None
            wavelengths = None

            for k in keys:
                item = data[k]
                if item.ndim == 3 and cube is None:
                    cube = item
                elif item.ndim == 1 and wavelengths is None:
                    wavelengths = item

            if cube is None:
                raise ValueError(f"No 3D array found in .npz archive: {filepath}")

            bands = cube.shape[2]
            if wavelengths is None or len(wavelengths) != bands:
                wavelengths = np.linspace(400, 750, bands)

            source = f"Loaded .npz HSI Cube ({cube.shape[0]}x{cube.shape[1]}x{bands})"
            return cube.astype(np.float32), wavelengths, source

        elif ext == ".mat":
            try:
                import scipy.io as sio
                mat = sio.loadmat(filepath)
                cube = None
                wavelengths = None
                for k, v in mat.items():
                    if not k.startswith("__") and isinstance(v, np.ndarray):
                        if v.ndim == 3 and cube is None:
                            cube = v
                        elif v.ndim in (1, 2) and (v.shape[0] == 1 or v.shape[1] == 1) and wavelengths is None:
                            wavelengths = v.flatten()

                if cube is None:
                    raise ValueError(f"No 3D data cube found in .mat file: {filepath}")

                bands = cube.shape[2]
                if wavelengths is None or len(wavelengths) != bands:
                    wavelengths = np.linspace(400, 750, bands)

                source = f"Loaded .mat HSI Cube ({cube.shape[0]}x{cube.shape[1]}x{bands})"
                return cube.astype(np.float32), wavelengths, source
            except ImportError:
                raise ImportError("scipy package is required to load MAT files.")

        else:
            raise ValueError(f"Unsupported spectral file format: {ext}")


# ============================================================
# MODULE: spectrum/spectral_plot.py
# ============================================================

# ============================================================
# HYPERLUMA + SPECTRUM Integration
# spectrum/spectral_plot.py - Embedded PyQt Matplotlib Graph
# ============================================================

import sys
import numpy as np
from loguru import logger

# Dual PyQt5 / PyQt6 import abstraction
try:
    from PyQt5.QtCore import Qt, QEvent
    from PyQt5.QtWidgets import QWidget, QVBoxLayout, QHBoxLayout, QPushButton, QLabel
except ImportError:
    from PyQt6.QtCore import Qt, QEvent
    from PyQt6.QtWidgets import QWidget, QVBoxLayout, QHBoxLayout, QPushButton, QLabel

import matplotlib
matplotlib.use("QtAgg")
from matplotlib.backends.backend_qtagg import FigureCanvasQTAgg, NavigationToolbar2QT
from matplotlib.figure import Figure


class SpectralPlotWidget(QWidget):
    """
    Embedded PyQt graph widget displaying Hyperspectral Intensity/Reflectance vs Wavelength (nm).
    Supports mean spectrum curves, shaded standard deviation bands, dynamic updates, and zooming.
    """

    def __init__(self, parent=None):
        super().__init__(parent)
        self.figure = Figure(figsize=(5, 3.5), dpi=100, facecolor="#FFFFFF")
        self.canvas = FigureCanvasQTAgg(self.figure)
        self.ax = self.figure.add_subplot(111)

        self._current_entries = []
        self._current_wavelengths = None
        self._click_artists = []
        self._active_band_range = None
        self._band_span_artist = None
        self._default_msg = "Click graph to inspect points (400 - 750 nm)"
        self._last_coord_text = self._default_msg

        self._init_ui()
        self.clear_graph()

    def _init_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(4)

        # Embedded Matplotlib navigation toolbar
        self.toolbar = NavigationToolbar2QT(self.canvas, self)

        # Remove Home and arrow buttons (Back & Forward) per user request
        for act in list(self.toolbar.actions()):
            if act.text() in ("Home", "Back", "Forward"):
                self.toolbar.removeAction(act)
        toolbar_actions = self.toolbar.actions()
        if toolbar_actions and toolbar_actions[0].isSeparator():
            self.toolbar.removeAction(toolbar_actions[0])

        self.toolbar.setFixedHeight(32)
        self.toolbar.setStyleSheet("""
            QToolBar { background: #F8FAFC; border: 1px solid #CBD5E0; border-radius: 6px; padding: 2px; }
            QToolButton { background: transparent; border: none; padding: 2px; }
            QToolButton:hover { background: #EEF4FF; border-radius: 4px; }
            QLabel {
                color: #0F172A;
                background-color: #FFFFFF;
                border: 1px solid #CBD5E0;
                border-radius: 4px;
                padding: 2px 8px;
                font-size: 8.5pt;
                font-weight: bold;
            }
        """)

        # Intercept toolbar set_message so text is never cleared on mouse leave
        orig_set_message = self.toolbar.set_message

        def custom_set_message(s):
            if s and s.strip():
                self._last_coord_text = s
                orig_set_message(s)
            else:
                orig_set_message(self._last_coord_text)

        self.toolbar.set_message = custom_set_message
        self.toolbar.set_message(self._default_msg)

        # Allow clicking the toolbar / coordinate bar to show text
        self.toolbar.installEventFilter(self)
        for lbl in self.toolbar.findChildren(QLabel):
            lbl.installEventFilter(self)

        # Connect click event on canvas to inspect points
        self.canvas.mpl_connect("button_press_event", self._on_canvas_click)

        layout.addWidget(self.canvas, stretch=1)

    def eventFilter(self, watched, event):
        press_type = getattr(QEvent.Type, "MouseButtonPress", None) or getattr(QEvent, "MouseButtonPress", 2)
        release_type = getattr(QEvent.Type, "MouseButtonRelease", None) or getattr(QEvent, "MouseButtonRelease", 3)
        if event.type() in (press_type, release_type):
            if watched == self.toolbar or isinstance(watched, QLabel):
                msg = self._last_coord_text if self._last_coord_text else self._default_msg
                self.toolbar.set_message(msg)
        return super().eventFilter(watched, event)

    def _on_canvas_click(self, event):
        if event.inaxes != self.ax:
            return
        if event.xdata is None or event.ydata is None:
            return

        wl = float(event.xdata)
        val = float(event.ydata)

        best_y = val
        best_label = "Point"
        best_diff = float("inf")

        if self._current_entries:
            for entry in self._current_entries:
                mean_spec = entry.get("mean_spectrum")
                if mean_spec is not None and len(mean_spec) > 0:
                    bands = len(mean_spec)
                    wls = (
                        self._current_wavelengths
                        if (self._current_wavelengths is not None and len(self._current_wavelengths) == bands)
                        else np.linspace(400, 750, bands)
                    )
                    idx = int(np.argmin(np.abs(wls - wl)))
                    cur_y = float(mean_spec[idx])
                    if abs(cur_y - val) < best_diff:
                        best_diff = abs(cur_y - val)
                        best_y = cur_y
                        best_label = entry.get("label", "ROI")

        if best_diff < 0.25:
            msg = f"{best_label}: Wavelength = {wl:.1f} nm | Intensity = {best_y:.3f}"
            marker_y = best_y
        else:
            msg = f"Selected: Wavelength = {wl:.1f} nm | Intensity = {val:.3f}"
            marker_y = val

        self._last_coord_text = msg
        self.toolbar.set_message(msg)
        self._update_click_marker(wl, marker_y, msg)

    def _update_click_marker(self, wl: float, val: float, text: str):
        if self._click_artists:
            for artist in self._click_artists:
                try:
                    artist.remove()
                except Exception:
                    pass
            self._click_artists = []

        try:
            line = self.ax.axvline(x=wl, color="#DC2626", linestyle=":", linewidth=1.5, alpha=0.85)
            dot = self.ax.plot(wl, val, marker="o", markersize=6, color="#DC2626", zorder=10)[0]
            annot = self.ax.annotate(
                f"{wl:.0f} nm\n{val:.3f}",
                xy=(wl, val),
                xytext=(8, 8),
                textcoords="offset points",
                bbox=dict(boxstyle="round,pad=0.3", fc="#FEF2F2", ec="#EF4444", lw=1.2, alpha=0.95),
                fontsize=8,
                fontweight="bold",
                color="#991B1B",
                zorder=11,
            )
            self._click_artists.extend([line, dot, annot])
            self.canvas.draw_idle()
        except Exception as exc:
            logger.debug(f"Click marker render: {exc}")

    def _configure_axes(self, wavelengths: np.ndarray | None = None, title: str = "Hyperspectral Spectral Signature"):
        self.ax.clear()
        self.ax.set_facecolor("#FFFFFF")
        self.ax.set_title(title, color="#1A2B4A", fontsize=11, fontweight="bold", pad=8)
        self.ax.set_xlabel("Wavelength (nm)", color="#1A2B4A", fontsize=9, fontweight="bold")
        self.ax.set_ylabel("Spectral Intensity / Reflectance", color="#1A2B4A", fontsize=9, fontweight="bold")
        self.ax.tick_params(colors="#475569", labelsize=8)
        self.ax.grid(True, color="#E2E8F0", linewidth=0.8, linestyle="--")

        for spine in self.ax.spines.values():
            spine.set_color("#CBD5E0")

        min_wl = float(wavelengths[0]) if (wavelengths is not None and len(wavelengths) > 1) else 400.0
        max_wl = float(wavelengths[-1]) if (wavelengths is not None and len(wavelengths) > 1) else 750.0
        self.ax.set_xlim(min_wl, max_wl)

        if abs(min_wl - 400.0) < 5 and abs(max_wl - 750.0) < 5:
            ticks = list(range(400, 751, 50))
            self.ax.set_xticks(ticks)
            self.ax.set_xticklabels([str(t) for t in ticks], fontsize=7, rotation=35, ha="right", rotation_mode="anchor")
        else:
            ticks = np.linspace(min_wl, max_wl, 21)
            self.ax.set_xticks(ticks)
            self.ax.set_xticklabels([f"{int(t)}" if abs(t - round(t)) < 0.01 else f"{t:.1f}" for t in ticks], fontsize=7, rotation=35, ha="right", rotation_mode="anchor")
        self.ax.set_ylim(0.0, 1.0)

        # Custom coordinate formatting for toolbar hover display
        def format_coord(x, y):
            return f"Wavelength: {x:.1f} nm | Intensity: {y:.3f}"
        self.ax.format_coord = format_coord

        self._apply_active_band_span()

    def set_active_band(self, min_wl: float | None, max_wl: float | None, label: str = ""):
        """Highlight active wavelength band with a semi-transparent colored span."""
        self._active_band_range = (min_wl, max_wl, label) if (min_wl is not None and max_wl is not None) else None
        # Per user request, do not show the line/span in the graph when band is selected
        # self._apply_active_band_span()
        # self.canvas.draw_idle()

    def _apply_active_band_span(self):
        # We keep this method for backwards compatibility, but it does nothing now
        pass

    def clear_graph(self, message: str = "Select a Pixel or ROI on Detected Image to view Spectrum"):
        self._current_entries = []
        self._current_wavelengths = None
        if self._click_artists:
            for artist in self._click_artists:
                try:
                    artist.remove()
                except Exception:
                    pass
            self._click_artists = []
        self._last_coord_text = self._default_msg
        if hasattr(self, "toolbar"):
            self.toolbar.set_message(self._default_msg)
        self._configure_axes()
        self.ax.text(
            0.5, 0.5,
            message,
            transform=self.ax.transAxes,
            ha="center", va="center",
            color="#94A3B8", fontsize=10, style="italic"
        )
        self.figure.tight_layout()
        self.canvas.draw_idle()

    def update_spectra(
        self,
        entries: list[dict],
        wavelengths: np.ndarray | None = None,
        title: str = "Hyperspectral Spectral Signature",
    ):
        """
        Updates plot with list of ROI spectrum entries.
        Each entry dict:
            {
                "label": str,
                "mean_spectrum": np.ndarray (Bands,),
                "std_spectrum": np.ndarray or None,
                "color": (R, G, B) tuple or hex string,
                "has_std": bool
            }
        """
        self._current_entries = entries
        self._current_wavelengths = wavelengths
        self._click_artists = []
        self._last_coord_text = f"{len(entries)} ROI Curve(s) | Click graph to inspect points"
        self.toolbar.set_message(self._last_coord_text)
        self._configure_axes(wavelengths, title)

        if not entries:
            self.clear_graph()
            return

        all_y = []

        for entry in entries:
            label = entry.get("label", "ROI")
            mean_spec = entry.get("mean_spectrum")
            std_spec = entry.get("std_spectrum")
            color_val = entry.get("color", "#2A7BDE")

            if isinstance(color_val, (tuple, list)):
                # Convert BGR tuple to RGB float tuple
                color_hex = (color_val[2] / 255.0, color_val[1] / 255.0, color_val[0] / 255.0)
            else:
                color_hex = color_val

            if mean_spec is not None and len(mean_spec) > 0:
                bands = len(mean_spec)
                if wavelengths is not None and len(wavelengths) == bands:
                    x_vals = wavelengths
                else:
                    x_vals = np.linspace(400, 750, bands)

                # Plot mean spectrum line
                self.ax.plot(
                    x_vals,
                    mean_spec,
                    color=color_hex,
                    linewidth=2.2,
                    label=label,
                )
                all_y.extend(mean_spec.tolist())



        if all_y:
            ymin, ymax = float(np.min(all_y)), float(np.max(all_y))
            y_margin = max(0.05, (ymax - ymin) * 0.1)
            self.ax.set_ylim(max(0.0, ymin - y_margin), ymax + y_margin)

        min_wl = float(wavelengths[0]) if (wavelengths is not None and len(wavelengths) > 1) else 400.0
        max_wl = float(wavelengths[-1]) if (wavelengths is not None and len(wavelengths) > 1) else 750.0
        self.ax.set_xlim(min_wl, max_wl)
        if abs(min_wl - 400.0) < 5 and abs(max_wl - 750.0) < 5:
            ticks = list(range(400, 751, 50))
            self.ax.set_xticks(ticks)
            self.ax.set_xticklabels([str(t) for t in ticks], fontsize=7, rotation=35, ha="right", rotation_mode="anchor")
        else:
            ticks = np.linspace(min_wl, max_wl, 21)
            self.ax.set_xticks(ticks)
            self.ax.set_xticklabels([f"{int(t)}" if abs(t - round(t)) < 0.01 else f"{t:.1f}" for t in ticks], fontsize=7, rotation=35, ha="right", rotation_mode="anchor")

        self.ax.legend(
            facecolor="#FFFFFF",
            edgecolor="#CBD5E0",
            labelcolor="#1A2B4A",
            fontsize=8,
            loc="upper right",
        )
        self.figure.tight_layout()
        self.canvas.draw_idle()


