import os
import csv
import numpy as np
from datetime import datetime
from loguru import logger

try:
    from PyQt5.QtWidgets import QFileDialog, QMessageBox
except ImportError:
    from PyQt6.QtWidgets import QFileDialog, QMessageBox

# [Bundled] from .roi_selector import ROIItem


class SpectralExporter:
    """
    Exports spectral data curves and ROI statistics to CSV files.
    """

    @staticmethod
    def export_to_csv(
        parent_widget,
        roi_entries: list[dict],
        wavelengths: np.ndarray | None,
        patient_id: str = "Unknown",
        image_name: str = "Unknown",
        disease_result: str = "Unknown",
        confidence: float = 0.0,
    ) -> bool:
        """
        Prompts user for save location and exports ROI spectra to CSV.
        """
        if not roi_entries:
            QMessageBox.warning(parent_widget, "Export Warning", "No ROI spectral curves to export.")
            return False

        default_filename = f"spectral_analysis_{patient_id}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv"
        filepath, _ = QFileDialog.getSaveFileName(
            parent_widget,
            "Export Spectral Data to CSV",
            default_filename,
            "CSV Files (*.csv);;All Files (*)",
        )

        if not filepath:
            return False

        try:
            with open(filepath, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)

                # 1. Metadata Header
                writer.writerow(["# =========================================================="])
                writer.writerow(["# HYPERLUMA + SPECTRUM Spectral Analysis Export"])
                writer.writerow(["# =========================================================="])
                writer.writerow(["# Patient ID", patient_id])
                writer.writerow(["# Image Name", image_name])
                writer.writerow(["# AI Disease Detection", disease_result])
                writer.writerow(["# AI Confidence (%)", f"{confidence:.2f}"])
                writer.writerow(["# Export Timestamp", datetime.now().strftime("%Y-%m-%d %H:%M:%S")])
                writer.writerow(["# ROI Count", len(roi_entries)])

                for idx, entry in enumerate(roi_entries, start=1):
                    writer.writerow([
                        f"# ROI {idx} Label", entry.get("label", "ROI"),
                        "Type", entry.get("type", "Unknown"),
                        "Pixels", entry.get("pixel_count", 0),
                    ])
                writer.writerow([])

                # 2. Spectral Data Table Columns
                # Wavelength(nm) | ROI_1_Mean | ROI_1_Std | ROI_2_Mean ...
                headers = ["Wavelength_nm"]
                for entry in roi_entries:
                    lbl = entry.get("label", "ROI").replace(" ", "_")
                    headers.append(f"{lbl}_Mean")
                    if entry.get("has_std", False):
                        headers.append(f"{lbl}_StdDev")

                writer.writerow(headers)

                # 3. Write rows per band
                sample_spectrum = roi_entries[0].get("mean_spectrum")
                if sample_spectrum is None:
                    QMessageBox.warning(parent_widget, "Export Error", "Invalid spectral data.")
                    return False

                num_bands = len(sample_spectrum)
                if wavelengths is None or len(wavelengths) != num_bands:
                    wavelengths = np.linspace(400, 750, num_bands)

                for b_idx in range(num_bands):
                    row = [f"{wavelengths[b_idx]:.2f}"]
                    for entry in roi_entries:
                        mean_spec = entry.get("mean_spectrum")
                        std_spec = entry.get("std_spectrum")

                        m_val = mean_spec[b_idx] if (mean_spec is not None and b_idx < len(mean_spec)) else 0.0
                        row.append(f"{m_val:.6f}")

                        if entry.get("has_std", False):
                            s_val = std_spec[b_idx] if (std_spec is not None and b_idx < len(std_spec)) else 0.0
                            row.append(f"{s_val:.6f}")

                    writer.writerow(row)

            logger.info(f"Spectral data exported successfully to {filepath}")
            QMessageBox.information(
                parent_widget,
                "Export Complete",
                f"Spectral data exported successfully to:\n\n{filepath}",
            )
            return True

        except Exception as exc:
            logger.error(f"Failed to export spectral CSV: {exc}")
            QMessageBox.critical(parent_widget, "Export Error", f"Could not save CSV file:\n{exc}")
            return False


