    def set_data(
        self,
        original_bgr: np.ndarray,
        detected_bgr: np.ndarray | None = None,
        attention_overlay_bgr: np.ndarray | None = None,
        disease_name: str = "Normal",
        confidence: float = 0.0,
        patient_id: str = "Unknown",
        image_name: str = "Image",
    ):
        """
        Updates the 3-Column View with new image, AI attention map, and prediction data.
        Constructs/loads the HSI spectral data cube automatically.
        """
        if original_bgr is None or original_bgr.size == 0:
            return

        self.current_original_bgr = original_bgr.copy()
        det_img = (detected_bgr if detected_bgr is not None else original_bgr).copy()
        self.current_detected_bgr = det_img.copy()

        if attention_overlay_bgr is not None and attention_overlay_bgr.size > 0:
            self.current_attention_bgr = attention_overlay_bgr.copy()
        else:
            self.current_attention_bgr = self.current_detected_bgr.copy()

        self.disease_name = disease_name
        self.disease_confidence = confidence
        self.patient_id = patient_id
        self.image_filename = image_name

        # Update Column 1 Viewer (Original Fundus Image)
        self.col1_viewer.set_image(self.current_original_bgr)
        h, w = self.current_original_bgr.shape[:2]
        ch = self.current_original_bgr.shape[2] if self.current_original_bgr.ndim == 3 else 1
        self.col1_meta_label.setText(f"Image: {image_name} | Res: {w}x{h} px | Channels: {ch}")

        # Update Column 2 Viewer (AI Detection / Attention Overlay or Active Band)
        current_band = self.band_combo.currentIndex() if hasattr(self, "band_combo") else 0
        if current_band > 0:
            data = self.band_combo.itemData(current_band)
            if data is not None:
                min_wl, max_wl = data
                self._current_band_range = (min_wl, max_wl)
                band_img = self._get_band_image(min_wl, max_wl, current_band)
                if band_img is not None:
                    self.col2_viewer.set_image(band_img, reset_zoom=False)
                self.plot_widget.set_active_band(min_wl, max_wl, self.band_combo.itemText(current_band))
        else:
            if self.show_attention and self.current_attention_bgr is not None:
                self.col2_viewer.set_image(self.current_attention_bgr, reset_zoom=False)
            else:
                self.col2_viewer.set_image(self.current_detected_bgr, reset_zoom=False)
            self._current_band_range = None
            self.plot_widget.set_active_band(None, None)

        self.disease_label.setText(f"Disease: {disease_name}")
        self.conf_label.setText(f"Confidence: {confidence:.1f}%")

        # Reconstruct / load HSI spectral cube
        try:
            cube, wavelengths, source_str = self.cube_loader.load_cube_from_image(self.current_original_bgr)
            self.spectral_cube = cube
            self.current_wavelengths = wavelengths
            self.wavelength_mgr.set_wavelengths(wavelengths)
            self.cube_info_label.setText(f"HSI Cube: {source_str}")
            logger.info(f"Loaded spectral cube for {image_name}: {source_str}")
        except Exception as exc:
            logger.error(f"Failed to generate HSI cube: {exc}")
            self.cube_info_label.setText("HSI Cube: Error loading data")

        # Clear existing ROIs & graph
        self._clear_rois()

    def _toggle_attention_overlay(self):
        self.show_attention = not self.show_attention
        if hasattr(self, "btn_toggle_attention") and self.btn_toggle_attention is not None:
            if self.show_attention:
                self.btn_toggle_attention.setChecked(True)
            else:
                self.btn_toggle_attention.setChecked(False)

        if self.show_attention:
            if self.current_attention_bgr is not None:
                self.col2_viewer.set_image(self.current_attention_bgr, reset_zoom=False)
        else:
            idx = getattr(self, "_current_band_index", 0)
            if idx > 0 and getattr(self, "_current_band_range", None) is not None:
                band_img = self._get_band_image(self._current_band_range[0], self._current_band_range[1], idx)
                if band_img is not None:
                    self.col2_viewer.set_image(band_img, reset_zoom=False)
                else:
                    if self.current_detected_bgr is not None:
                        self.col2_viewer.set_image(self.current_detected_bgr, reset_zoom=False)
            else:
                if self.current_detected_bgr is not None:
                    self.col2_viewer.set_image(self.current_detected_bgr, reset_zoom=False)

    def _set_roi_mode(self, mode: ROIType):
        self.btn_rect.setChecked(mode == ROIType.RECTANGLE)
        self.btn_circle.setChecked(mode == ROIType.CIRCLE)
        self.col1_viewer.roi_selector.set_tool(mode)
        self.col2_viewer.roi_selector.set_tool(mode)

    def _clear_rois(self):
        self.col1_viewer.rois.clear()
        self.col2_viewer.rois.clear()
        self.col1_viewer.roi_selector.reset_current_drawing()
        self.col2_viewer.roi_selector.reset_current_drawing()
        self.col1_viewer.roi_selector.roi_counter = 1
        self.col2_viewer.roi_selector.roi_counter = 1
        self.col1_viewer.update_display()
        self.col2_viewer.update_display()
        self.plot_widget.clear_graph()
        self._update_roi_info_panel(None, None, {})
        self.export_csv_btn.setEnabled(False)

    def _on_coord_hovered(self, x: int, y: int):
        self.hover_coord_label.setText(f"Hover Pixel: (X: {x}, Y: {y})")

    def _on_band_changed(self, index: int):
        self._current_band_index = index
        data = self.band_combo.itemData(index) if hasattr(self.band_combo, "itemData") else None
        if data is None or index == 0:
            self._current_band_range = None
            if self.show_attention and self.current_attention_bgr is not None:
                self.col2_viewer.set_image(self.current_attention_bgr, reset_zoom=False)
            elif self.current_detected_bgr is not None:
                self.col2_viewer.set_image(self.current_detected_bgr, reset_zoom=False)
            self.plot_widget.set_active_band(None, None)
        else:
            # Turn off AI attention if a band is explicitly selected
            if self.show_attention:
                self.show_attention = False
                if hasattr(self, "btn_toggle_attention") and self.btn_toggle_attention is not None:
                    self.btn_toggle_attention.setChecked(False)
            min_wl, max_wl = data
            self._current_band_range = (min_wl, max_wl)
            band_img = self._get_band_image(min_wl, max_wl, index)
            if band_img is not None:
                self.col2_viewer.set_image(band_img, reset_zoom=False)
            self.plot_widget.set_active_band(min_wl, max_wl, self.band_combo.itemText(index))

        self.band_selected.emit(index, self._current_band_range)

    def _get_band_image(self, min_wl: float, max_wl: float, band_idx: int) -> np.ndarray | None:
        if self.spectral_cube is not None and self.current_wavelengths is not None:
            try:
                wls = self.current_wavelengths
                indices = np.where((wls >= min_wl) & (wls <= max_wl))[0]
                if len(indices) == 0:
                    indices = [int(np.argmin(np.abs(wls - (min_wl + max_wl) / 2.0)))]

                band_slice = np.mean(self.spectral_cube[:, :, indices], axis=2)
                norm = cv2.normalize(band_slice, None, 0, 255, cv2.NORM_MINMAX).astype(np.uint8)
                clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
                norm = clahe.apply(norm)

                ref = self.current_detected_bgr if self.current_detected_bgr is not None else self.current_original_bgr
                if ref is not None:
                    th, tw = ref.shape[:2]
                    if norm.shape[:2] != (th, tw):
                        norm = cv2.resize(norm, (tw, th), interpolation=cv2.INTER_LINEAR)

                if band_idx == 1:
                    return cv2.merge([norm, (norm * 0.75).astype(np.uint8), (norm * 0.25).astype(np.uint8)])
                elif band_idx == 2:
                    return cv2.merge([(norm * 0.15).astype(np.uint8), norm, (norm * 0.40).astype(np.uint8)])
                elif band_idx == 3:
                    return cv2.merge([(norm * 0.15).astype(np.uint8), (norm * 0.30).astype(np.uint8), norm])
                else:
                    return cv2.cvtColor(norm, cv2.COLOR_GRAY2BGR)
            except Exception as exc:
                logger.error(f"Failed to slice spectral cube: {exc}")

        # Fallback to direct analytical spectral band extraction from current frame/image
        ref = self.current_detected_bgr if self.current_detected_bgr is not None else self.current_original_bgr
        if ref is not None:
            return self.apply_band_filter_to_frame(ref, band_idx)
        return None

    def _load_hsi_file(self):
        filepath, _ = QFileDialog.getOpenFileName(
            self,
            "Open Hyperspectral File",
            "",
            "HSI Files (*.npy *.npz *.mat);;All Files (*)",
        )
        if not filepath:
            return
        try:
            cube, wavelengths, source = self.cube_loader.load_cube_from_file(filepath)
            self.spectral_cube = cube
            self.current_wavelengths = wavelengths
            self.wavelength_mgr.set_wavelengths(wavelengths)
            self.cube_info_label.setText(f"HSI Cube: {source}")
            self._clear_rois()
            QMessageBox.information(self, "HSI Loaded", f"Successfully loaded HSI dataset:\n{source}")
        except Exception as exc:
            QMessageBox.critical(self, "HSI Load Error", f"Could not load HSI file:\n{exc}")

    def _on_roi_created(self):
        if self.spectral_cube is None:
            img = self.current_original_bgr
            if img is None and self.col1_viewer.original_bgr is not None:
                img = self.col1_viewer.original_bgr
            if img is None and self.col2_viewer.original_bgr is not None:
                img = self.col2_viewer.original_bgr

            if img is not None and img.size > 0:
                try:
                    self.current_original_bgr = img.copy()
                    cube, wavelengths, source_str = self.cube_loader.load_cube_from_image(img)
                    self.spectral_cube = cube
                    self.current_wavelengths = wavelengths
                    self.wavelength_mgr.set_wavelengths(wavelengths)
                    self.cube_info_label.setText(f"HSI Cube: {source_str}")
                except Exception as exc:
                    logger.error(f"Failed to auto-generate spectral cube on ROI creation: {exc}")

        if self.spectral_cube is None or not self.col1_viewer.rois:
            return

        self.col1_viewer.update_display()
        self.col2_viewer.update_display()

        plot_entries = []
        last_stats = {}
        last_mean = None
        last_std = None

        for roi in self.col1_viewer.rois:
            mean_spec, std_spec, stats = SpectralExtractor.extract_roi_spectrum(
                self.spectral_cube, roi
            )
            if mean_spec is not None:
                plot_entries.append({
                    "label": roi.label,
                    "mean_spectrum": mean_spec,
                    "std_spectrum": std_spec,
                    "color": roi.color,
                    "has_std": stats.get("has_std", False),
                    "type": roi.roi_type.value,
                    "pixel_count": stats.get("pixel_count", 0),
                })
                last_mean = mean_spec
                last_std = std_spec
                last_stats = stats
                last_stats["roi_type"] = roi.roi_type.value

        if plot_entries:
            self.plot_widget.update_spectra(
                entries=plot_entries,
                wavelengths=self.current_wavelengths,
                title="Hyperspectral Spectral Signature Analysis ",
            )
            self._update_roi_info_panel(last_mean, last_std, last_stats)
            self.export_csv_btn.setEnabled(True)

    def _update_roi_info_panel(self, mean_spec: np.ndarray | None, std_spec: np.ndarray | None, stats: dict):
        """ROI information panel has been removed from the UI."""
        pass

    def _export_csv(self):
        if not self.col1_viewer.rois or self.spectral_cube is None:
            return

        roi_entries = []
        for roi in self.col1_viewer.rois:
            mean_spec, std_spec, stats = SpectralExtractor.extract_roi_spectrum(
                self.spectral_cube, roi
            )
            if mean_spec is not None:
                roi_entries.append({
                    "label": roi.label,
                    "mean_spectrum": mean_spec,
                    "std_spectrum": std_spec,
                    "has_std": stats.get("has_std", False),
                    "type": roi.roi_type.value,
                    "pixel_count": stats.get("pixel_count", 0),
                })

        SpectralExporter.export_to_csv(
            parent_widget=self,
            roi_entries=roi_entries,
            wavelengths=self.current_wavelengths,
            patient_id=self.patient_id,
            image_name=self.image_filename,
            disease_result=self.disease_name,
            confidence=self.disease_confidence,
        )


