def is_raspberry_pi() -> bool:
    """Check if running on a Raspberry Pi device."""
    try:
        if os.path.exists("/proc/device-tree/model"):
            with open("/proc/device-tree/model", "r") as f:
                return "raspberry pi" in f.read().lower()
    except Exception:
        pass
    return False


# ── Camera Worker ──────────────────────────────────────────
class CameraWorker(QThread):
    frame_ready = pyqtSignal(np.ndarray)
    opened      = pyqtSignal()
    error       = pyqtSignal(str)

    def __init__(self, camera_index: int = 0):
        super().__init__()
        self.camera_index = camera_index
        self.running      = False
        self.paused       = False
        self.camera       = None

    def run(self):
        self.running = True
        self.camera = CameraCapture(width=640, height=480, fps=15)
        camera = self.camera

        if not camera.open() or not self.running:
            if self.running:
                hint = (
                    "Cannot open camera. Verify camera connection or run install.sh "
                    "to configure system drivers."
                )
                self.error.emit(hint)
            camera.release()
            self.camera = None
            return

        consecutive_failures = 0
        has_emitted_opened = False

        while self.running:
            try:
                if not self.paused:
                    ret, frame = camera.read()
                    if ret and frame is not None and frame.size > 0:
                        consecutive_failures = 0
                        # Only activate the UI after libcamera has supplied a frame.
                        if not has_emitted_opened:
                            has_emitted_opened = True
                            self.opened.emit()
                        if self.running and not self.paused:
                            self.frame_ready.emit(frame)
                    else:
                        consecutive_failures += 1
                        logger.warning(f"Camera frame read drop #{consecutive_failures}")
                        self.msleep(50)
                        if consecutive_failures >= 5:
                            logger.warning("Camera feed frame read failed repeatedly. Attempting to reconnect...")
                            consecutive_failures = 0
                            self.msleep(300)
                            if not self.running:
                                break
                            if not camera.reconnect():
                                self.error.emit("Camera feed lost and cannot reconnect.")
                                break

                self.msleep(66)
            except Exception as e:
                logger.error(f"Error in CameraWorker run loop: {e}")
                self.msleep(50)

        if self.camera is not None:
            self.camera.release()
            self.camera = None

    def stop(self):
        self.running = False
        if not self.wait(200):
            if self.camera is not None:
                try:
                    self.camera.release()
                except Exception:
                    pass
                self.camera = None
            self.wait(150)

    def pause(self):  self.paused = True
    def resume(self): self.paused = False


# ── Video Worker ───────────────────────────────────────────
class VideoWorker(QThread):
    frame_ready = pyqtSignal(np.ndarray)
    finished    = pyqtSignal()
    error       = pyqtSignal(str)

    def __init__(self, video_path: str):
        super().__init__()
        self.video_path  = video_path
        self.running     = False
        self.paused      = False
        self._frame_pos  = 0

    def run(self):
        if not self.video_path or not os.path.exists(self.video_path):
            self.error.emit("Video file does not exist.")
            return

        cap = cv2.VideoCapture(self.video_path)
        if not cap.isOpened():
            cap.release()
            self.error.emit("Cannot open video file.")
            return

        if self._frame_pos > 0:
            cap.set(cv2.CAP_PROP_POS_FRAMES, self._frame_pos)

        self.running = True
        fps   = cap.get(cv2.CAP_PROP_FPS)
        delay = int(1000 / fps) if fps > 0 else 33
        delay = max(20, min(100, delay))

        while self.running:
            if not self.paused:
                ret, frame = cap.read()
                if ret and frame is not None:
                    self._frame_pos = int(cap.get(cv2.CAP_PROP_POS_FRAMES))
                    self.frame_ready.emit(frame)
                else:
                    self.finished.emit()
                    break
            self.msleep(delay)

        cap.release()

    def stop(self):
        self.running = False
        self.wait(1500)

    def pause(self):  self.paused = True
    def resume(self): self.paused = False


