# ── Inference Worker ───────────────────────────────────────
class InferenceWorker(QThread):
    results_ready = pyqtSignal(list, np.ndarray)  # (results, original_frame)
    error         = pyqtSignal(str)

    def __init__(self, predictor=None, skip_frames: int = 2):
        super().__init__()
        self.predictor     = predictor
        self.frame_queue   = queue.Queue(maxsize=1)
        self.running       = False
        # Initialize all counters & state as instance attributes to prevent UnboundLocalError
        self.frame_counter = 0
        self.skip_frames   = max(1, skip_frames)
        self.last_results  = []

    def set_predictor(self, predictor):
        self.predictor = predictor

    def predict_frame(self, frame: np.ndarray):
        if frame is None or self.predictor is None:
            return

        self.frame_counter += 1
        # Frame-skipping: process inference every Nth frame to reduce thermal/CPU load
        if self.frame_counter % self.skip_frames != 0:
            return

        # Safely put frame into queue without blocking Qt event loop
        try:
            if self.frame_queue.full():
                try:
                    self.frame_queue.get_nowait()
                except queue.Empty:
                    pass
            self.frame_queue.put_nowait(frame.copy())
        except (queue.Full, Exception):
            pass

    def run(self):
        self.running = True
        while self.running:
            try:
                frame = self.frame_queue.get(timeout=0.03)
            except queue.Empty:
                self.msleep(10)
                continue

            if not self.running:
                break

            if frame is None:
                continue

            try:
                results = self.predictor.predict(frame)
                if results and self.running:
                    self.last_results = results
                    self.results_ready.emit(results, frame)
            except Exception as e:
                logger.error(f"Inference worker error: {e}")
                if self.running:
                    self.error.emit(str(e))
            finally:
                try:
                    self.frame_queue.task_done()
                except ValueError:
                    pass

            self.msleep(10)

    def clear_queue(self):
        try:
            while not self.frame_queue.empty():
                self.frame_queue.get_nowait()
                self.frame_queue.task_done()
        except (queue.Empty, ValueError, Exception):
            pass

    def stop(self):
        self.running = False
        self.clear_queue()
        self.wait(500)


# ── Video Writer Worker ─────────────────────────────────────
class VideoWriterWorker(QThread):
    """Background worker to write video frames asynchronously."""
    def __init__(self, filepath: str, fps: int, width: int, height: int):
        super().__init__()
        self.filepath = filepath
        self.fps      = fps
        self.width    = width
        self.height   = height
        self.queue    = queue.Queue(maxsize=30)
        self.running  = False

    def write(self, frame: np.ndarray):
        if self.running and frame is not None and frame.size > 0:
            try:
                if self.queue.full():
                    try:
                        self.queue.get_nowait()
                    except queue.Empty:
                        pass
                self.queue.put_nowait(frame.copy())
            except Exception:
                pass

    def run(self):
        self.running = True
        writer = None
        writer_failed = False
        while self.running or not self.queue.empty():
            try:
                frame = self.queue.get(timeout=0.05)
                if frame is None or frame.size == 0 or writer_failed:
                    continue
                if writer is None:
                    fh, fw = frame.shape[:2]
                    try:
                        writer = cv2.VideoWriter(
                            self.filepath, cv2.VideoWriter_fourcc(*"MJPG"), self.fps, (fw, fh)
                        )
                        if not writer.isOpened():
                            logger.error(f"Failed to open VideoWriter for {self.filepath}")
                            writer_failed = True
                            continue
                    except Exception as exc:
                        logger.error(f"VideoWriter initialization failed: {exc}")
                        writer_failed = True
                        continue

                if writer is not None and writer.isOpened():
                    fh, fw = frame.shape[:2]
                    target_w, target_h = self.width, self.height
                    if (fw, fh) != (target_w, target_h):
                        try:
                            frame = cv2.resize(frame, (target_w, target_h))
                        except Exception:
                            pass
                    writer.write(frame)
                
                try:
                    self.queue.task_done()
                except ValueError:
                    pass
            except queue.Empty:
                continue
            except Exception as e:
                logger.error(f"Error writing video frame: {e}")
        if writer is not None:
            try:
                writer.release()
            except Exception:
                pass

    def release(self):
        self.running = False
        try:
            while not self.queue.empty():
                self.queue.get_nowait()
                self.queue.task_done()
        except Exception:
            pass
        if not self.wait(200):
            logger.warning("VideoWriterWorker thread did not finish cleanly")


# ── Save Worker ────────────────────────────────────────────
class SaveWorker(QThread):
    """Runs save operations in background — prevents UI freeze."""
    finished = pyqtSignal(str)   # save_path
    error    = pyqtSignal(str)

    def __init__(
        self, save_manager, report_generator,
        patient_id, original_frame, detected_frame,
        snapshots, result, model_name, timestamp
    ):
        super().__init__()
        self.save_manager      = save_manager
        self.report_generator  = report_generator
        self.patient_id        = patient_id
        self.original_frame    = original_frame
        self.detected_frame    = detected_frame
        self.snapshots         = snapshots
        self.result            = result
        self.model_name        = model_name
        self.timestamp         = timestamp

    def run(self):
        try:
            save_path = self.save_manager.save_all(
                patient_id     = self.patient_id,
                original_frame = self.original_frame,
                detected_frame = self.detected_frame,
                snapshots      = self.snapshots,
                result         = self.result,
                model_name     = self.model_name,
                timestamp      = self.timestamp,
            )
            self.report_generator.generate(
                save_path  = save_path,
                patient_id = self.patient_id,
                result     = self.result,
                model_name = self.model_name,
                timestamp  = self.timestamp,
            )
            self.finished.emit(save_path)
        except Exception as e:
            self.error.emit(str(e))


# ── File Upload Worker ─────────────────────────────────────
class FileUploadWorker(QThread):
    """Runs file copy & image loading asynchronously in background."""
    finished = pyqtSignal(str, object)  # (saved_path, frame_or_none)
    error    = pyqtSignal(str)

    def __init__(self, save_manager, src_path: str, patient_id: str, timestamp: str):
        super().__init__()
        self.save_manager = save_manager
        self.src_path     = src_path
        self.patient_id   = patient_id
        self.timestamp    = timestamp

    def run(self):
        try:
            ext = os.path.splitext(self.src_path)[1].lower()
            frame = None
            if ext in (".jpg", ".jpeg", ".png", ".bmp"):
                frame = cv2.imread(self.src_path)

            saved_path = self.src_path
            try:
                dest = self.save_manager.save_uploaded_file(self.src_path, self.patient_id, self.timestamp)
                if dest:
                    saved_path = dest
            except Exception as se:
                logger.warning(f"Could not copy uploaded file to patient folder: {se}")

            self.finished.emit(saved_path, frame)
        except Exception as e:
            self.error.emit(str(e))


# ── Snapshot Card ──────────────────────────────────────────
def apply_hyperspectral_gain(img: np.ndarray, gain: float = 6.0) -> np.ndarray:
    """
    Applies the fixed 6.0x hyperspectral acquisition gain safely without over-saturating
    fundus images into washed-out solid white frames.
    """
    if img is None or not isinstance(img, np.ndarray) or img.size == 0:
        return img
    mean_intensity = float(img.mean())
    if mean_intensity < 40:
        # Dark raw narrowband acquisition: apply proportional linear amplification up to 6.0x
        scale = min(gain, 255.0 / max(1.0, mean_intensity * 2.5))
        return cv2.convertScaleAbs(img, alpha=scale, beta=0)
    else:
        # Standard illuminated fundus image: apply dynamic range expansion with gamma-curve
        # so features and vessels are enhanced without clipping highlights to pure white
        inv_gamma = 1.0 / (1.0 + np.log10(max(1.0, gain)) * 0.35)
        table = np.array([((i / 255.0) ** inv_gamma) * 255 for i in range(256)]).astype("uint8")
        return cv2.LUT(img, table)


