def log_display_information(app: QApplication) -> None:
    """Write connected display information to the log."""
    screens = app.screens()

    if not screens:
        logger.warning("No display was detected")
        return

    for index, screen in enumerate(screens, start=1):
        geometry = screen.geometry()
        available = screen.availableGeometry()

        logger.info(
            "Display {}: name={} resolution={}x{} "
            "available={}x{} DPR={:.2f} logicalDPI={:.2f}",
            index,
            screen.name(),
            geometry.width(),
            geometry.height(),
            available.width(),
            available.height(),
            screen.devicePixelRatio(),
            screen.logicalDotsPerInch(),
        )


def apply_display_mode(
    window: MainWindow,
    app: QApplication,
) -> None:
    """Make the application fit the display."""
    screen = window.screen() or app.primaryScreen()

    if screen is None:
        logger.warning("Unable to determine the current display")
        window.show()
        return

    geometry = screen.geometry()

    logger.info(
        "Applying display mode: {}x{}",
        geometry.width(),
        geometry.height(),
    )

    if KIOSK_MODE:
        window.showFullScreen()
    else:
        window.showMaximized()


def connect_display_change_handlers(
    window: MainWindow,
    app: QApplication,
) -> None:
    """Reapply the display mode when display geometry changes."""
    connected_screens = set()

    def connect_screen(screen) -> None:
        if screen is None:
            return

        screen_name = screen.name()

        if screen_name in connected_screens:
            return

        connected_screens.add(screen_name)

        screen.geometryChanged.connect(
            lambda _geometry: QTimer.singleShot(
                100,
                lambda: apply_display_mode(window, app),
            )
        )

        screen.availableGeometryChanged.connect(
            lambda _geometry: QTimer.singleShot(
                100,
                lambda: apply_display_mode(window, app),
            )
        )

        screen.logicalDotsPerInchChanged.connect(
            lambda _dpi: QTimer.singleShot(
                100,
                lambda: apply_display_mode(window, app),
            )
        )

        logger.info(
            "Display-change handling enabled for {}",
            screen_name,
        )

    for current_screen in app.screens():
        connect_screen(current_screen)

    app.screenAdded.connect(connect_screen)

    def handle_screen_removed(_screen) -> None:
        QTimer.singleShot(
            200,
            lambda: apply_display_mode(window, app),
        )

    app.screenRemoved.connect(handle_screen_removed)

    window_handle = window.windowHandle()

    if window_handle is not None:
        window_handle.screenChanged.connect(
            lambda new_screen: (
                connect_screen(new_screen),
                QTimer.singleShot(
                    100,
                    lambda: apply_display_mode(window, app),
                ),
            )
        )


def ensure_pi_shortcuts_and_autostart() -> None:
    """Ensure Desktop icon and autostart desktop files exist on Raspberry Pi with direct execution."""
    try:
        if not sys.platform.startswith("linux"):
            return

        home_dir = os.path.expanduser("~")
        autostart_dir = os.path.join(home_dir, ".config", "autostart")
        desktop_dir = os.path.join(home_dir, "Desktop")
        icons_dir = os.path.join(home_dir, ".local", "share", "icons")
        os.makedirs(icons_dir, exist_ok=True)
        icon_path = os.path.join(icons_dir, "hyperluma_logo.png")

        # Automatically extract embedded logo to icon_path if missing
        if not os.path.exists(icon_path):
            try:
                with open(icon_path, "wb") as f_ico:
                    f_ico.write(base64.b64decode(SMARTLAB_LOGO_BASE64))
            except Exception as e:
                logger.warning(f"Could not save icon for desktop shortcut: {e}")

        this_file = os.path.abspath(__file__)
        this_dir = os.path.dirname(this_file)

        sh_launcher = os.path.join(this_dir, "run_hyperluma_pi.sh")
        if os.path.exists(sh_launcher):
            exec_cmd = f'/bin/bash "{sh_launcher}"'
        else:
            exec_cmd = f'/usr/bin/python3 "{this_file}"'

        autostart_file = os.path.join(autostart_dir, "hyperluma.desktop")
        desktop_shortcut = os.path.join(desktop_dir, "HYPERLUMA.desktop")

        desktop_entry_content = (
            "[Desktop Entry]\n"
            "Type=Application\n"
            "Name=HYPERLUMA - Eye Disease Detection\n"
            "Comment=AI-Based Eye Disease Detection System\n"
            f"Exec={exec_cmd}\n"
            f"Icon={icon_path}\n"
            f"Path={this_dir}\n"
            "Terminal=false\n"
            "StartupNotify=true\n"
            "Categories=Healthcare;Science;Education;\n"
            "X-GNOME-Autostart-enabled=true\n"
        )

        # 1. Ensure Desktop Shortcut exists and is directly executable on double click
        if os.path.exists(desktop_dir):
            try:
                with open(desktop_shortcut, "w", encoding="utf-8") as f:
                    f.write(desktop_entry_content)
                os.chmod(desktop_shortcut, 0o755)
                os.system(f"gio set '{desktop_shortcut}' metadata::trusted true 2>/dev/null")
                logger.info(f"Desktop shortcut created/verified at {desktop_shortcut}")
            except Exception as d_err:
                logger.warning(f"Could not write desktop shortcut: {d_err}")

        # 2. Ensure Autostart configuration exists on Pi devices
        if os.path.exists("/home/smartlab") or os.path.exists("/proc/device-tree/model") or os.path.exists("/etc/rpi-issue"):
            os.makedirs(autostart_dir, exist_ok=True)
            if not os.path.exists(autostart_file):
                with open(autostart_file, "w", encoding="utf-8") as f:
                    f.write(desktop_entry_content)
                os.chmod(autostart_file, 0o755)
                logger.info(f"Autostart configuration created at {autostart_file}")

        # 3. Configure PCManFM / libfm to execute without prompting on double-click
        for cfg in [
            os.path.join(home_dir, ".config", "libfm", "libfm.conf"),
            os.path.join(home_dir, ".config", "pcmanfm", "LXDE-pi", "pcmanfm.conf")
        ]:
            if os.path.exists(cfg):
                try:
                    with open(cfg, "r", encoding="utf-8", errors="ignore") as f:
                        lines = f.readlines()
                    updated = False
                    new_lines = []
                    for line in lines:
                        if line.strip().startswith("quick_exec="):
                            new_lines.append("quick_exec=1\n")
                            updated = True
                        elif line.strip().startswith("dont_ask_before_exec="):
                            new_lines.append("dont_ask_before_exec=1\n")
                            updated = True
                        else:
                            new_lines.append(line)
                    if updated:
                        with open(cfg, "w", encoding="utf-8") as f:
                            f.writelines(new_lines)
                except Exception:
                    pass

    except Exception as exc:
        logger.warning(f"Could not configure system desktop shortcut/autostart: {exc}")


def main() -> None:
    """Launch the HYPERLUMA application."""
    logger.info("Starting HYPERLUMA - Eye Disease Detection System")
    logger.info("SMART - Sanjivani Multidisciplinary AI Research & Technology")

    app = QApplication(sys.argv)

    app.setApplicationName("HYPERLUMA")
    app.setApplicationDisplayName("HYPERLUMA - Eye Disease Detection System")
    app.setApplicationVersion("1.0.0")
    app.setOrganizationName("SMART - Sanjivani Multidisciplinary AI Research & Technology")

    font_family = "DejaVu Sans" if sys.platform.startswith("linux") else "Segoe UI"
    application_font = QFont(font_family)
    application_font.setPixelSize(16)
    app.setFont(application_font)

    log_display_information(app)

    ensure_pi_shortcuts_and_autostart()

    try:
        window = MainWindow()
        window.setMinimumSize(320, 240)

        apply_display_mode(window, app)

        QTimer.singleShot(
            0,
            lambda: connect_display_change_handlers(window, app),
        )

        logger.info("HYPERLUMA launched successfully")

        exit_code = app.exec() if hasattr(app, "exec") else app.exec_()

        logger.info(
            "HYPERLUMA closed with exit code {}",
            exit_code,
        )

        sys.exit(exit_code)

    except Exception:
        logger.exception("HYPERLUMA failed to start because of an unexpected error")
        raise


if __name__ == "__main__":
    main()